/**
 * ShipD Geometry Generator for Frontend Visualization
 *
 * Converts ShipD parameter vectors and geometry data from backend into Three.js geometry
 * for 3D visualization. Uses geometry generated by backend ShipDHullGeometryService when available,
 * or generates geometry directly from ShipD parameters.
 *
 * @module shipdGeometryGenerator
 */

import * as THREE from "three";
import type { ShipDParameterMetadata } from "../types/sizing";
import { createCubicSpline, evaluateSpline } from "./splineInterpolation";
import {
  generateControlPointGridFromOffsets,
  evaluateSurface,
  getResolutionMultiplier,
  type NurbsQuality,
} from "./nurbsSurface";

// ============================================================================
// TYPES & INTERFACES
// ============================================================================

/**
 * Hull station (transverse section) from ShipD geometry
 */
export interface ShipDHullStation {
  position: number; // 0 = aft, 1 = forward
  offsets: Record<number, number>; // height (m) -> half-breadth (m)
  hasBulb?: boolean;
  bulbOffsets?: Record<number, number>;
  hasSkeg?: boolean;
  skegOffsets?: Record<number, number>;
}

/**
 * Hull sections data from backend
 */
export interface ShipDHullSections {
  stations: ShipDHullStation[];
  stationPositions: number[];
}

/**
 * Parameters for generating ShipD hull geometry
 */
export interface ShipDGeometryParams {
  /** ShipD 45-parameter vector (normalized 0-1) */
  shipdVector: number[];
  /** Length between perpendiculars (m) */
  lppM: number;
  /** Maximum beam (m) */
  beamM: number;
  /** Design draft (m) */
  draftM: number;
  /** ShipD parameter metadata for denormalization */
  metadata: ShipDParameterMetadata[];
  /** Resolution factor (1.0 = default, higher = more detail) */
  resolution?: number;
}

// ============================================================================
// MAIN FUNCTIONS
// ============================================================================

/**
 * Generates 3D hull geometry from ShipD parameter vector or backend geometry data
 */
export function generateShipDHull3D(
  params:
    | ShipDGeometryParams
    | {
        sections: ShipDHullSections;
        lppM: number;
        smooth?: boolean;
        stationMultiplier?: number;
        heightMultiplier?: number;
        useNurbs?: boolean;
        nurbsQuality?: NurbsQuality;
      }
): THREE.BufferGeometry {
  // If sections are provided (from backend), use them directly
  if ("sections" in params) {
    const draftM =
      "draftM" in params && typeof params.draftM === "number" ? params.draftM : undefined;
    return generateHull3DFromSections(
      params.sections,
      params.lppM,
      params.smooth ?? true,
      params.stationMultiplier,
      params.heightMultiplier,
      params.useNurbs ?? true,
      params.nurbsQuality ?? "medium",
      draftM // Pass draftM if available to ensure waterplane alignment
    );
  }

  // Otherwise, generate from ShipD vector
  const sections = generateShipDSections(params);
  return generateHull3DFromSections(sections, params.lppM, true, 5, 5, true, "high");
}

/**
 * Generates hull sections from ShipD parameter vector
 */
export function generateShipDSections(
  params: ShipDGeometryParams,
  stationCount: number = 20
): ShipDHullSections {
  const { shipdVector, lppM, beamM, draftM, metadata, resolution = 1.0 } = params;

  if (shipdVector.length !== 45) {
    throw new Error(
      `ShipD vector must contain exactly 45 parameters (received ${shipdVector.length})`
    );
  }

  // Denormalize key parameters
  const denormalized = denormalizeParameters(shipdVector, metadata);

  // LOG KEY PARAMETERS for debugging (debug level to reduce noise during optimization)
  // Note: vector[1] and vector[2] are already ratios, not denormalized
  console.debug("[ShipD Geometry] Key parameters:", {
    longitudinal: {
      bow_length: shipdVector[1]?.toFixed(2),
      stern_length: shipdVector[2]?.toFixed(2),
      mid_length: (1.0 - shipdVector[1] - shipdVector[2])?.toFixed(2),
    },
    bow: {
      flare_deg: denormalized[8]?.toFixed(1),
      curvature: denormalized[9]?.toFixed(2),
      knuckle: denormalized[10]?.toFixed(2),
      kappa_bow: denormalized[14]?.toFixed(2),
      deadrise_deg: denormalized[19]?.toFixed(1),
    },
    midship: {
      sheer_enabled: denormalized[20] > 0.5,
      tumblehome_enabled: denormalized[21] > 0.5,
    },
    stern: {
      atrans: denormalized[22]?.toFixed(2),
      kappa_stern: denormalized[24]?.toFixed(2),
      rake_deg: denormalized[27]?.toFixed(1),
      transom_width: denormalized[28]?.toFixed(2),
      curvature: denormalized[29]?.toFixed(2),
      knuckle: denormalized[30]?.toFixed(2),
    },
    bulb: {
      enabled: shipdVector[31] > 0.5,
      length: shipdVector[33]?.toFixed(2), // Ratio - use directly
      height: shipdVector[34]?.toFixed(2), // Ratio - use directly
      width: shipdVector[35]?.toFixed(2), // Ratio - use directly
      asymmetry: shipdVector[36]?.toFixed(2), // Ratio - use directly
      fillet: shipdVector[37]?.toFixed(2), // Ratio - use directly
    },
  });

  // Extract longitudinal proportions with validation and fallbacks
  // IMPORTANT: vector[1] and vector[2] are already ratios (0-1), NOT normalized values
  // They should NOT be denormalized - they ARE the actual ratios
  let lb = shipdVector[1]; // Bow length ratio (Lb from ShipD) - already a ratio
  let ls = shipdVector[2]; // Stern length ratio (Ls from ShipD) - already a ratio

  // VALIDATION: ShipD parameters should be reasonable
  // Lb and Ls are ratios of Lpp, typically 0.15-0.45 each
  const MIN_BOW_LENGTH = 0.15; // Minimum 15% for bow
  const MIN_STERN_LENGTH = 0.15; // Minimum 15% for stern
  const MAX_BOW_LENGTH = 0.45; // Maximum 45% for bow
  const MAX_STERN_LENGTH = 0.45; // Maximum 45% for stern

  // Check if values are unrealistic (missing metadata, bad data, or extreme edge cases)
  const needsFallback =
    lb == null ||
    ls == null ||
    isNaN(lb) ||
    isNaN(ls) ||
    lb < MIN_BOW_LENGTH ||
    ls < MIN_STERN_LENGTH ||
    lb > MAX_BOW_LENGTH ||
    ls > MAX_STERN_LENGTH ||
    lb + ls > 0.85; // Ensure at least 15% midship

  if (needsFallback) {
    // Debug log instead of warn - this is expected behavior during optimization
    // when parameters may temporarily be out of bounds
    console.debug(
      "[ShipD Geometry] Invalid longitudinal proportions detected, using fallback values:",
      {
        original: { lb, ls, sum: lb + ls },
        reason:
          lb == null || ls == null || isNaN(lb) || isNaN(ls)
            ? "Missing or invalid values"
            : lb < MIN_BOW_LENGTH || ls < MIN_STERN_LENGTH
              ? "Too short"
              : lb > MAX_BOW_LENGTH || ls > MAX_STERN_LENGTH
                ? "Too long"
                : lb + ls > 0.85
                  ? "Sum exceeds 85%"
                  : "Unknown",
      }
    );

    // Realistic fallback: typical container ship proportions
    lb = 0.3; // 30% bow
    ls = 0.3; // 30% stern

    // Debug log instead of regular log to reduce noise
    console.debug("[ShipD Geometry] Using fallback proportions:", {
      bow: "30%",
      midship: "40%",
      stern: "30%",
    });
  }

  const lm = 1.0 - lb - ls; // Mid-body length ratio

  // Calculate boundaries
  const bowStart = ls + lm; // Start of bow region (0 = aft)
  const midStart = ls; // Start of mid-body region

  const stations: ShipDHullStation[] = [];
  const stationPositions: number[] = [];

  const effectiveStationCount = Math.max(10, Math.round(stationCount * resolution));

  // Generate stations
  for (let i = 0; i < effectiveStationCount; i++) {
    const stationPos = i / (effectiveStationCount - 1); // 0 = aft, 1 = forward
    stationPositions.push(stationPos);

    // Determine which region this station is in
    const region = stationPos < midStart ? "stern" : stationPos < bowStart ? "midship" : "bow";

    // Generate offsets for this station
    const offsets = generateStationOffsets(
      stationPos,
      region,
      denormalized,
      shipdVector,
      lppM,
      beamM,
      draftM,
      metadata
    );

    // Check for bulb (only in bow region)
    // CRITICAL: bit flags should use normalized vector directly, not denormalized
    const hasBulb = region === "bow" && shipdVector[31] > 0.5; // bit_BB
    let bulbOffsets: Record<number, number> | undefined;

    if (hasBulb) {
      bulbOffsets = generateBulbOffsets(stationPos, denormalized, shipdVector, lppM, beamM, draftM);
    }

    // Check for skeg (only in stern region)
    const hasSkeg = region === "stern" && shipdVector[32] > 0.5; // bit_SB
    let skegOffsets: Record<number, number> | undefined;

    if (hasSkeg) {
      skegOffsets = generateSkegOffsets(stationPos, denormalized, shipdVector, lppM, beamM, draftM);
    }

    stations.push({
      position: stationPos,
      offsets,
      hasBulb,
      bulbOffsets,
      hasSkeg,
      skegOffsets,
    });
  }

  return { stations, stationPositions };
}

/**
 * Generates bulb geometry from ShipD parameters
 */
export function generateShipDBulb(
  shipdVector: number[],
  _lppM: number,
  beamM: number,
  draftM: number,
  _metadata: ShipDParameterMetadata[]
): THREE.BufferGeometry | null {
  if (shipdVector.length !== 45) {
    return null;
  }

  // Check if bulb is enabled
  if (shipdVector[31] <= 0.5) {
    return null; // bit_BB
  }

  // Bulb parameters - these are ratios, use vector directly
  // const lbb = shipdVector[33]; // Bulb length ratio - not used in ellipsoid generation
  const hbb = shipdVector[34]; // Bulb height ratio
  const bbb = shipdVector[35]; // Bulb width ratio
  // const lbbm = denormalized[36]; // Bulb asymmetry - not used in simplified implementation
  // const rbb = denormalized[37]; // Bulb radius - not used in simplified implementation

  // const bulbLength = lbb * lppM; // Not used in simplified implementation
  const bulbHeight = hbb * draftM;
  const bulbWidth = bbb * beamM;

  // Generate ellipsoid geometry for bulb
  const geometry = new THREE.BufferGeometry();
  const vertices: number[] = [];
  const indices: number[] = [];

  const segments = 16;
  const rings = 8;

  // Generate vertices
  for (let ring = 0; ring <= rings; ring++) {
    const v = ring / rings;
    const y = -bulbHeight + v * bulbHeight * 2; // Vertical position

    for (let seg = 0; seg <= segments; seg++) {
      const u = seg / segments;
      const theta = u * Math.PI * 2;

      // Ellipsoid shape
      const radius = (bulbWidth / 2) * Math.sqrt(1 - Math.pow(y / bulbHeight, 2));
      const x = Math.cos(theta) * radius;
      const z = Math.sin(theta) * radius;

      vertices.push(x, y, z);
    }
  }

  // Generate faces
  for (let ring = 0; ring < rings; ring++) {
    for (let seg = 0; seg < segments; seg++) {
      const a = ring * (segments + 1) + seg;
      const b = ring * (segments + 1) + seg + 1;
      const c = (ring + 1) * (segments + 1) + seg;
      const d = (ring + 1) * (segments + 1) + seg + 1;

      indices.push(a, b, c);
      indices.push(b, d, c);
    }
  }

  geometry.setAttribute("position", new THREE.Float32BufferAttribute(vertices, 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();

  return geometry;
}

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

/**
 * Interpolates hull sections to increase resolution for smooth 3D rendering
 * Uses cubic spline interpolation to create smooth surfaces
 */
function interpolateSections(
  sections: ShipDHullSections,
  stationMultiplier: number = 2,
  heightMultiplier: number = 2
): ShipDHullSections {
  if (sections.stations.length === 0) {
    return sections;
  }

  // Use imported spline utilities for smooth interpolation

  const interpolatedStations: ShipDHullSections["stations"] = [];
  const interpolatedPositions: number[] = [];

  // Get all unique heights across all stations
  const allHeights = new Set<number>();
  for (const station of sections.stations) {
    for (const height of Object.keys(station.offsets).map(Number)) {
      if (Number.isFinite(height)) {
        allHeights.add(height);
      }
    }
  }
  const sortedHeights = Array.from(allHeights).sort((a, b) => a - b);

  // Interpolate stations (longitudinal)
  const originalPositions = sections.stations.map((s) => s.position).sort((a, b) => a - b);
  const numInterpStations = Math.max(
    sections.stations.length,
    Math.floor(sections.stations.length * stationMultiplier)
  );

  for (let i = 0; i < numInterpStations; i++) {
    const t = i / (numInterpStations - 1);
    const targetPos =
      originalPositions[0] +
      t * (originalPositions[originalPositions.length - 1] - originalPositions[0]);

    // Find surrounding stations for interpolation
    let lowerIdx = -1;
    let upperIdx = -1;
    for (let j = 0; j < originalPositions.length; j++) {
      if (originalPositions[j] <= targetPos) {
        lowerIdx = j;
      }
      if (originalPositions[j] >= targetPos && upperIdx === -1) {
        upperIdx = j;
        break;
      }
    }

    // Get surrounding stations
    const lowerStation =
      lowerIdx >= 0
        ? sections.stations.find((s) => Math.abs(s.position - originalPositions[lowerIdx]) < 0.001)
        : null;
    const upperStation =
      upperIdx >= 0
        ? sections.stations.find((s) => Math.abs(s.position - originalPositions[upperIdx]) < 0.001)
        : null;

    if (!lowerStation && !upperStation) continue;
    if (lowerStation && !upperStation) {
      // Use lower station
      interpolatedStations.push({ ...lowerStation, position: targetPos });
      interpolatedPositions.push(targetPos);
      continue;
    }
    if (!lowerStation && upperStation) {
      // Use upper station
      interpolatedStations.push({ ...upperStation, position: targetPos });
      interpolatedPositions.push(targetPos);
      continue;
    }

    // Interpolate between lower and upper stations
    const lowerPos = lowerStation!.position;
    const upperPos = upperStation!.position;
    const posRange = upperPos - lowerPos;
    const interpFactor = posRange > 0.001 ? (targetPos - lowerPos) / posRange : 0;

    // Interpolate offsets at each height
    const interpolatedOffsets: Record<number, number> = {};
    for (const height of sortedHeights) {
      const lowerOffset = lowerStation!.offsets[height] ?? 0;
      const upperOffset = upperStation!.offsets[height] ?? 0;
      interpolatedOffsets[height] = lowerOffset + interpFactor * (upperOffset - lowerOffset);
    }

    interpolatedStations.push({
      position: targetPos,
      offsets: interpolatedOffsets,
      hasBulb: lowerStation!.hasBulb || upperStation!.hasBulb,
    });
    interpolatedPositions.push(targetPos);
  }

  // Interpolate heights (vertical) for each station
  const numInterpHeights = Math.max(
    sortedHeights.length,
    Math.floor(sortedHeights.length * heightMultiplier)
  );
  const interpolatedHeights: number[] = [];
  if (sortedHeights.length > 0) {
    const minHeight = sortedHeights[0];
    const maxHeight = sortedHeights[sortedHeights.length - 1];
    for (let i = 0; i < numInterpHeights; i++) {
      const t = i / (numInterpHeights - 1);
      interpolatedHeights.push(minHeight + t * (maxHeight - minHeight));
    }
  }

  // For each interpolated station, interpolate offsets at interpolated heights
  // CRITICAL: Ensure all stations use the exact same height set for proper mesh connectivity
  // This prevents gaps between stations when creating mesh faces
  for (const station of interpolatedStations) {
    const originalHeights = Object.keys(station.offsets)
      .map(Number)
      .filter((h) => Number.isFinite(h))
      .sort((a, b) => a - b);

    const newOffsets: Record<number, number> = {};

    if (originalHeights.length < 2) {
      // If insufficient points, create offsets at all interpolated heights using nearest neighbor
      for (const height of interpolatedHeights) {
        // Find nearest original height
        let nearestHeight = originalHeights[0] ?? 0;
        let minDist = Infinity;
        for (const origH of originalHeights) {
          const dist = Math.abs(origH - height);
          if (dist < minDist) {
            minDist = dist;
            nearestHeight = origH;
          }
        }
        newOffsets[height] = Math.max(0, station.offsets[nearestHeight] ?? 0);
      }
      station.offsets = newOffsets;
      continue;
    }

    // Create smooth spline through original points
    const points = originalHeights.map((h) => ({
      x: h,
      y: station.offsets[h] ?? 0,
    }));

    // Create spline segments for evaluation
    const segments = createCubicSpline(points);

    // CRITICAL: Evaluate spline at exact interpolatedHeights values
    // This ensures all stations have identical height keys, preventing mesh gaps
    for (const height of interpolatedHeights) {
      if (Number.isFinite(height)) {
        const interpolatedY = evaluateSpline(segments, height);
        newOffsets[height] = Math.max(0, interpolatedY);
      }
    }

    station.offsets = newOffsets;
  }

  return {
    stations: interpolatedStations,
    stationPositions: interpolatedPositions,
  };
}

/**
 * Generates 3D hull geometry from ShipD sections using NURBS surface evaluation
 * Creates smooth C² continuous surfaces
 */
function generateHull3DFromSectionsNurbs(
  sections: ShipDHullSections,
  lppM: number,
  quality: NurbsQuality = "medium",
  draftM?: number // Optional draft to ensure vertices exist at waterplane position
): THREE.BufferGeometry {
  const geometry = new THREE.BufferGeometry();
  const vertices: number[] = [];
  const indices: number[] = [];

  // === DEFENSIVE VALIDATION ===
  // Validate inputs before NURBS evaluation to prevent NaN propagation
  if (!sections || !sections.stations || sections.stations.length === 0) {
    console.warn("[ShipD NURBS] Invalid sections input:", sections);
    return geometry;
  }
  if (!Number.isFinite(lppM) || lppM <= 0) {
    console.error("[ShipD NURBS] Invalid lppM:", lppM);
    return geometry;
  }

  // Validate all station offsets are finite
  for (const station of sections.stations) {
    if (!Number.isFinite(station.position)) {
      console.error("[ShipD NURBS] Invalid station position:", station.position);
      return geometry;
    }
    for (const [height, halfBreadth] of Object.entries(station.offsets)) {
      const h = Number(height);
      const hb = Number(halfBreadth);
      if (!Number.isFinite(h) || !Number.isFinite(hb)) {
        console.error("[ShipD NURBS] Invalid offset detected:", {
          stationPos: station.position,
          height: h,
          halfBreadth: hb,
        });
        return geometry;
      }
    }
  }

  // Convert sections to offset grid format
  const stations: number[] = sections.stations.map((s) => s.position);
  const allHeights = new Set<number>();
  for (const station of sections.stations) {
    for (const height of Object.keys(station.offsets).map(Number)) {
      if (Number.isFinite(height)) {
        allHeights.add(height);
      }
    }
  }
  const waterlines = Array.from(allHeights).sort((a, b) => a - b);

  if (waterlines.length === 0) {
    return geometry;
  }

  // Create offsets grid: offsets[stationIndex][waterlineIndex] = halfBreadth
  const offsets: number[][] = [];
  for (let sIdx = 0; sIdx < stations.length; sIdx++) {
    const station = sections.stations[sIdx];
    const stationOffsets: number[] = [];
    for (let wIdx = 0; wIdx < waterlines.length; wIdx++) {
      const height = waterlines[wIdx];
      const halfBreadth = station.offsets[height] ?? 0;
      // CRITICAL: Validate half-breadth to prevent NaN in NURBS evaluation
      const validHalfBreadth = Number.isFinite(halfBreadth) ? Math.max(0, halfBreadth) : 0;
      stationOffsets.push(validHalfBreadth);
    }
    offsets.push(stationOffsets);
  }

  // Normalize stations and waterlines to [0, 1] range for NURBS evaluation
  const stationMin = Math.min(...stations);
  const stationMax = Math.max(...stations);
  const stationRange = stationMax - stationMin || 1;
  const normalizedStations = stations.map((s) => (s - stationMin) / stationRange);

  const waterlineMin = Math.min(...waterlines);
  const waterlineMax = Math.max(...waterlines);
  const waterlineRange = waterlineMax - waterlineMin || 1;
  const normalizedWaterlines = waterlines.map((w) => (w - waterlineMin) / waterlineRange);

  // CRITICAL: Ensure draft position is included if provided and not already in waterlines
  // This ensures waterplane intersects correctly with hull
  if (draftM !== undefined && !waterlines.some((w) => Math.abs(w - draftM) < 0.001)) {
    // Add draft to waterlines if it's not already there
    waterlines.push(draftM);
    waterlines.sort((a, b) => a - b);

    // Recalculate normalized waterlines
    const newWaterlineMin = Math.min(...waterlines);
    const newWaterlineMax = Math.max(...waterlines);
    const newWaterlineRange = newWaterlineMax - newWaterlineMin || 1;
    normalizedWaterlines.length = 0;
    normalizedWaterlines.push(...waterlines.map((w) => (w - newWaterlineMin) / newWaterlineRange));

    // Add offsets for draft position by interpolating from adjacent waterlines
    const draftIdx = waterlines.indexOf(draftM);
    for (let sIdx = 0; sIdx < offsets.length; sIdx++) {
      // Find adjacent waterlines for interpolation
      const lowerIdx = draftIdx > 0 ? draftIdx - 1 : 0;
      const upperIdx = draftIdx < waterlines.length - 1 ? draftIdx + 1 : waterlines.length - 1;
      const lowerHeight = waterlines[lowerIdx];
      const upperHeight = waterlines[upperIdx];
      const lowerHb = offsets[sIdx]?.[lowerIdx] ?? 0;
      const upperHb = offsets[sIdx]?.[upperIdx] ?? 0;

      // Linear interpolation for draft position
      let draftHb = 0;
      if (Math.abs(upperHeight - lowerHeight) > 0.001) {
        const t = (draftM - lowerHeight) / (upperHeight - lowerHeight);
        draftHb = lowerHb + t * (upperHb - lowerHb);
      } else {
        draftHb = lowerHb;
      }

      // Insert draft offset at correct position
      offsets[sIdx].splice(draftIdx, 0, Math.max(0, draftHb));
    }

    // Update ranges
    const updatedWaterlineMin = Math.min(...waterlines);
    const updatedWaterlineMax = Math.max(...waterlines);
    const updatedWaterlineRange = updatedWaterlineMax - updatedWaterlineMin || 1;
    // Re-normalize (already done above, but update range variables)
    Object.assign({
      waterlineMin: updatedWaterlineMin,
      waterlineMax: updatedWaterlineMax,
      waterlineRange: updatedWaterlineRange,
    });
  }

  // Estimate beam and draft from offsets
  const maxHalfBreadth = Math.max(...offsets.flat().map((hb) => hb || 0));
  const estimatedBeam = maxHalfBreadth * 2;
  const estimatedDraft = waterlineRange || 1;
  const estimatedLpp = stationRange || 1;

  // Generate control point grid from offset points
  const controlPointGrid = generateControlPointGridFromOffsets(
    normalizedStations,
    normalizedWaterlines,
    offsets,
    estimatedLpp,
    estimatedBeam,
    estimatedDraft
  );

  // HYBRID APPROACH: First, add vertices at ORIGINAL offset points (preserves exact geometry)
  // Then add intermediate points between original points for smoothness
  const resolutionMultiplier = getResolutionMultiplier(quality);

  // Build evaluation point sets: original points + intermediate points
  const uEvaluationPoints: number[] = [];
  const vEvaluationPoints: number[] = [];

  // Add original station positions (normalized for NURBS evaluation)
  for (let i = 0; i < normalizedStations.length; i++) {
    uEvaluationPoints.push(normalizedStations[i]);
    // Add intermediate points between this and next station
    if (i < normalizedStations.length - 1) {
      const uStart = normalizedStations[i];
      const uEnd = normalizedStations[i + 1];
      for (let j = 1; j < resolutionMultiplier; j++) {
        const t = j / resolutionMultiplier;
        uEvaluationPoints.push(uStart + t * (uEnd - uStart));
      }
    }
  }

  // Add original waterline positions (normalized for NURBS evaluation)
  for (let i = 0; i < normalizedWaterlines.length; i++) {
    vEvaluationPoints.push(normalizedWaterlines[i]);
    // Add intermediate points between this and next waterline
    if (i < normalizedWaterlines.length - 1) {
      const vStart = normalizedWaterlines[i];
      const vEnd = normalizedWaterlines[i + 1];
      for (let j = 1; j < resolutionMultiplier; j++) {
        const t = j / resolutionMultiplier;
        vEvaluationPoints.push(vStart + t * (vEnd - vStart));
      }
    }
  }

  // CRITICAL: Ensure draft position is included in evaluation points if provided
  // This ensures waterplane intersects correctly with hull
  if (draftM !== undefined) {
    const draftNormalized = (draftM - waterlineMin) / waterlineRange;
    // Check if draft is already in evaluation points (within tolerance)
    const draftExists = vEvaluationPoints.some((v) => Math.abs(v - draftNormalized) < 1e-6);
    if (!draftExists && draftNormalized >= 0 && draftNormalized <= 1) {
      // Insert draft at correct sorted position
      vEvaluationPoints.push(draftNormalized);
      vEvaluationPoints.sort((a, b) => a - b);
    }
  }

  // Sort evaluation points to ensure proper ordering
  uEvaluationPoints.sort((a, b) => a - b);
  vEvaluationPoints.sort((a, b) => a - b);

  // Track which evaluation points correspond to original offset positions
  const originalUIndices = new Set<number>();
  const originalVIndices = new Set<number>();
  for (let i = 0; i < normalizedStations.length; i++) {
    const u = normalizedStations[i];
    const idx = uEvaluationPoints.findIndex((up) => Math.abs(up - u) < 1e-10);
    if (idx >= 0) originalUIndices.add(idx);
  }
  for (let i = 0; i < normalizedWaterlines.length; i++) {
    const v = normalizedWaterlines[i];
    const idx = vEvaluationPoints.findIndex((vp) => Math.abs(vp - v) < 1e-10);
    if (idx >= 0) originalVIndices.add(idx);
  }

  // Evaluate NURBS surface at all evaluation points
  // CRITICAL: Use exact original offset values at original points, NURBS interpolation for intermediate points
  // Three.js: X = transverse (half-breadth), Y = vertical (height), Z = longitudinal (station)
  // Center hull at origin: longitudinal from -lpp/2 (aft) to +lpp/2 (forward)
  for (let vIdx = 0; vIdx < vEvaluationPoints.length; vIdx++) {
    const v = vEvaluationPoints[vIdx];
    const isOriginalV = originalVIndices.has(vIdx);

    // For original waterline positions, use exact waterline value
    // For intermediate positions (including draft if not in original waterlines), denormalize from NURBS evaluation
    let height: number;
    if (isOriginalV) {
      const originalVIdx = normalizedWaterlines.findIndex((nv) => Math.abs(nv - v) < 1e-10);
      height = originalVIdx >= 0 ? waterlines[originalVIdx] : waterlineMin + v * waterlineRange;
    } else {
      // Check if this is the draft position
      if (draftM !== undefined) {
        const draftNormalized = (draftM - waterlineMin) / waterlineRange;
        if (Math.abs(v - draftNormalized) < 1e-6) {
          height = draftM; // Use exact draft value
        } else {
          height = waterlineMin + v * waterlineRange;
        }
      } else {
        height = waterlineMin + v * waterlineRange;
      }
    }

    for (let uIdx = 0; uIdx < uEvaluationPoints.length; uIdx++) {
      const u = uEvaluationPoints[uIdx];
      const isOriginalU = originalUIndices.has(uIdx);

      // For original station positions, use exact station value
      let stationPos: number;
      if (isOriginalU) {
        const originalUIdx = normalizedStations.findIndex((nu) => Math.abs(nu - u) < 1e-10);
        stationPos = originalUIdx >= 0 ? stations[originalUIdx] : stationMin + u * stationRange;
      } else {
        stationPos = stationMin + u * stationRange;
      }
      const z = (stationPos - 0.5) * lppM; // Center at origin: 0 -> -lpp/2, 1 -> +lpp/2

      // For original offset points (both u and v are original), use exact offset value
      // For interpolated points, evaluate NURBS surface
      let halfBreadth: number;
      if (isOriginalU && isOriginalV) {
        const originalUIdx = normalizedStations.findIndex((nu) => Math.abs(nu - u) < 1e-10);
        const originalVIdx = normalizedWaterlines.findIndex((nv) => Math.abs(nv - v) < 1e-10);
        if (originalUIdx >= 0 && originalVIdx >= 0) {
          // Use exact original offset value
          halfBreadth = Number(offsets[originalUIdx]?.[originalVIdx] ?? 0);
        } else {
          // Fallback to NURBS evaluation
          const [, normalizedY] = evaluateSurface(controlPointGrid, u, v);
          halfBreadth = normalizedY * (estimatedBeam / 2);
        }
      } else {
        // Interpolated point: evaluate NURBS surface
        const [, normalizedY] = evaluateSurface(controlPointGrid, u, v);
        halfBreadth = normalizedY * (estimatedBeam / 2);
      }

      // === CRITICAL: Validate vertex before adding to prevent NaN ===
      if (!Number.isFinite(halfBreadth) || !Number.isFinite(height) || !Number.isFinite(z)) {
        console.error("[ShipD NURBS] NaN detected in vertex calculation:", {
          halfBreadth,
          height,
          z,
          u,
          v,
        });
        // Skip this vertex (will create holes, but better than crashing THREE.js)
        continue;
      }

      // Port side (negative X)
      vertices.push(-halfBreadth, height, z);
    }
  }

  // Generate indices for triangles using evaluation grid
  const numUPoints = uEvaluationPoints.length;
  for (let vIdx = 0; vIdx < vEvaluationPoints.length - 1; vIdx++) {
    for (let uIdx = 0; uIdx < uEvaluationPoints.length - 1; uIdx++) {
      const a = vIdx * numUPoints + uIdx;
      const b = a + 1;
      const c = a + numUPoints;
      const d = c + 1;

      // Two triangles per quad (port side)
      indices.push(a, c, b);
      indices.push(b, c, d);
    }
  }

  // Mirror to starboard side
  const portVertexCount = vertices.length / 3;
  const portStartIndex = portVertexCount;

  for (let vIdx = 0; vIdx < vEvaluationPoints.length; vIdx++) {
    for (let uIdx = 0; uIdx < uEvaluationPoints.length; uIdx++) {
      const idx = vIdx * numUPoints + uIdx;
      const baseIdx = idx * 3;
      const x = vertices[baseIdx];
      const y = vertices[baseIdx + 1];
      const z = vertices[baseIdx + 2];

      // === CRITICAL: Validate starboard vertices ===
      if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(z)) {
        console.error("[ShipD NURBS] NaN in starboard mirror:", { x, y, z });
        continue;
      }

      // Starboard side (positive X, mirrored)
      vertices.push(-x, y, z);
    }
  }

  // Generate indices for starboard side
  for (let vIdx = 0; vIdx < vEvaluationPoints.length - 1; vIdx++) {
    for (let uIdx = 0; uIdx < uEvaluationPoints.length - 1; uIdx++) {
      const a = portStartIndex + vIdx * numUPoints + uIdx;
      const b = a + 1;
      const c = a + numUPoints;
      const d = c + 1;

      indices.push(a, b, c);
      indices.push(b, d, c);
    }
  }

  // CRITICAL: Use ORIGINAL offset values for bow/stern closing faces
  // Don't evaluate NURBS at bow/stern - use actual data to preserve shape characteristics
  const lastStationIdx = stations.length - 1;
  const bowStationPos = stations[lastStationIdx];
  const bowZ = (bowStationPos - 0.5) * lppM;

  // Create centerline vertices at bow tip for each ORIGINAL waterline
  const bowCenterlineVertices: number[] = [];
  for (let wlIdx = 0; wlIdx < waterlines.length; wlIdx++) {
    const height = waterlines[wlIdx];
    if (!Number.isFinite(height)) continue;
    const centerlineVertexIdx = vertices.length / 3;
    vertices.push(0, height, bowZ);
    bowCenterlineVertices.push(centerlineVertexIdx);
  }

  // Create closing faces using ORIGINAL offset values at bow
  for (let wlIdx = 0; wlIdx < waterlines.length - 1; wlIdx++) {
    // Find vertex indices for bow station at these waterlines
    const v1Idx = vEvaluationPoints.findIndex((v) => {
      const normalizedV = (waterlines[wlIdx] - waterlineMin) / waterlineRange;
      return Math.abs(v - normalizedV) < 1e-10;
    });
    const v2Idx = vEvaluationPoints.findIndex((v) => {
      const normalizedV = (waterlines[wlIdx + 1] - waterlineMin) / waterlineRange;
      return Math.abs(v - normalizedV) < 1e-10;
    });
    const uBowIdx = uEvaluationPoints.findIndex((u) => {
      const normalizedU = (bowStationPos - stationMin) / stationRange;
      return Math.abs(u - normalizedU) < 1e-10;
    });

    if (v1Idx >= 0 && v2Idx >= 0 && uBowIdx >= 0) {
      const aPort = v1Idx * numUPoints + uBowIdx;
      const bPort = v2Idx * numUPoints + uBowIdx;
      const aStarboard = portStartIndex + aPort;
      const bStarboard = portStartIndex + bPort;
      const centerA = bowCenterlineVertices[wlIdx];
      const centerB = bowCenterlineVertices[wlIdx + 1];

      // Use ORIGINAL offset values
      const hb1 = Number(offsets[lastStationIdx]?.[wlIdx] ?? 0);
      const hb2 = Number(offsets[lastStationIdx]?.[wlIdx + 1] ?? 0);

      if (centerA !== undefined && centerB !== undefined && (hb1 > 0 || hb2 > 0)) {
        if (hb1 > 0) {
          indices.push(aPort, aStarboard, centerA);
        }
        if (hb2 > 0) {
          indices.push(bPort, bStarboard, centerB);
        }
        if (hb1 > 0 && hb2 > 0) {
          indices.push(aPort, bPort, centerB);
          indices.push(aPort, centerB, centerA);
          indices.push(aStarboard, centerA, centerB);
          indices.push(aStarboard, centerB, bStarboard);
        }
      }
    }
  }

  // CRITICAL: Use ORIGINAL offset values for stern closing faces
  // Detect transom vs canoe from ORIGINAL offsets, not NURBS-evaluated values
  const firstStationIdx = 0;
  const sternStationPos = stations[firstStationIdx];
  const sternZ = (sternStationPos - 0.5) * lppM;

  // Check if stern has width (transom) or tapers to point (canoe) using ORIGINAL offsets
  const maxSternHalfBreadth = Math.max(
    ...(offsets[firstStationIdx] ?? []).map((hb) => Number(hb) || 0)
  );
  const isTransomStern = maxSternHalfBreadth > 0.05 * estimatedBeam; // 5% of beam threshold

  if (isTransomStern) {
    // TRANSOM STERN: Create flat closing face using ORIGINAL offset values
    for (let wlIdx = 0; wlIdx < waterlines.length - 1; wlIdx++) {
      const v1Idx = vEvaluationPoints.findIndex((v) => {
        const normalizedV = (waterlines[wlIdx] - waterlineMin) / waterlineRange;
        return Math.abs(v - normalizedV) < 1e-10;
      });
      const v2Idx = vEvaluationPoints.findIndex((v) => {
        const normalizedV = (waterlines[wlIdx + 1] - waterlineMin) / waterlineRange;
        return Math.abs(v - normalizedV) < 1e-10;
      });
      const uSternIdx = uEvaluationPoints.findIndex((u) => {
        const normalizedU = (sternStationPos - stationMin) / stationRange;
        return Math.abs(u - normalizedU) < 1e-10;
      });

      if (v1Idx >= 0 && v2Idx >= 0 && uSternIdx >= 0) {
        const aPort = v1Idx * numUPoints + uSternIdx;
        const bPort = v2Idx * numUPoints + uSternIdx;
        const aStarboard = portStartIndex + aPort;
        const bStarboard = portStartIndex + bPort;

        // Use ORIGINAL offset values
        const hb1 = Number(offsets[firstStationIdx]?.[wlIdx] ?? 0);
        const hb2 = Number(offsets[firstStationIdx]?.[wlIdx + 1] ?? 0);

        if (hb1 > 0.0001 || hb2 > 0.0001) {
          indices.push(aStarboard, aPort, bStarboard);
          indices.push(bStarboard, aPort, bPort);
        }
      }
    }
  } else {
    // CANOE/CRUISER STERN: Close to centerline using ORIGINAL offset values
    const sternCenterlineVertices: number[] = [];
    for (let wlIdx = 0; wlIdx < waterlines.length; wlIdx++) {
      const height = waterlines[wlIdx];
      if (!Number.isFinite(height)) continue;
      const centerlineVertexIdx = vertices.length / 3;
      vertices.push(0, height, sternZ);
      sternCenterlineVertices.push(centerlineVertexIdx);
    }

    for (let wlIdx = 0; wlIdx < waterlines.length - 1; wlIdx++) {
      const v1Idx = vEvaluationPoints.findIndex((v) => {
        const normalizedV = (waterlines[wlIdx] - waterlineMin) / waterlineRange;
        return Math.abs(v - normalizedV) < 1e-10;
      });
      const v2Idx = vEvaluationPoints.findIndex((v) => {
        const normalizedV = (waterlines[wlIdx + 1] - waterlineMin) / waterlineRange;
        return Math.abs(v - normalizedV) < 1e-10;
      });
      const uSternIdx = uEvaluationPoints.findIndex((u) => {
        const normalizedU = (sternStationPos - stationMin) / stationRange;
        return Math.abs(u - normalizedU) < 1e-10;
      });

      if (v1Idx >= 0 && v2Idx >= 0 && uSternIdx >= 0) {
        const aPort = v1Idx * numUPoints + uSternIdx;
        const bPort = v2Idx * numUPoints + uSternIdx;
        const aStarboard = portStartIndex + aPort;
        const bStarboard = portStartIndex + bPort;
        const centerA = sternCenterlineVertices[wlIdx];
        const centerB = sternCenterlineVertices[wlIdx + 1];

        // Use ORIGINAL offset values
        const hb1 = Number(offsets[firstStationIdx]?.[wlIdx] ?? 0);
        const hb2 = Number(offsets[firstStationIdx]?.[wlIdx + 1] ?? 0);

        if (centerA !== undefined && centerB !== undefined && (hb1 > 0 || hb2 > 0)) {
          if (hb1 > 0) {
            indices.push(aPort, aStarboard, centerA);
          }
          if (hb2 > 0) {
            indices.push(bPort, bStarboard, centerB);
          }
          if (hb1 > 0 && hb2 > 0) {
            indices.push(aPort, bPort, centerB);
            indices.push(aPort, centerB, centerA);
            indices.push(aStarboard, centerA, centerB);
            indices.push(aStarboard, centerB, bStarboard);
          }
        }
      }
    }
  }

  geometry.setIndex(indices);
  geometry.setAttribute("position", new THREE.Float32BufferAttribute(vertices, 3));
  geometry.computeVertexNormals();
  geometry.computeBoundingBox();

  return geometry;
}

/**
 * Generates 3D geometry from hull sections
 * Uses smooth interpolation to create high-resolution, smooth surfaces
 */
function generateHull3DFromSections(
  sections: ShipDHullSections,
  lppM: number,
  smooth: boolean = true,
  stationMultiplier: number = 3,
  heightMultiplier: number = 3,
  useNurbs: boolean = true,
  nurbsQuality: NurbsQuality = "medium",
  draftM?: number // Optional draft to ensure vertices exist at waterplane position
): THREE.BufferGeometry {
  // CRITICAL: Sort stations by position to ensure correct ordering (aft to forward: 0 to 1)
  // This prevents helical twist in 3D view if stations are not in correct order
  const sortedSections = {
    ...sections,
    stations: [...sections.stations].sort((a, b) => a.position - b.position),
  };

  // Try NURBS surface evaluation for smooth rendering if requested and enabled
  if (smooth && useNurbs && sortedSections.stations.length >= 4) {
    try {
      return generateHull3DFromSectionsNurbs(sortedSections, lppM, nurbsQuality, draftM);
    } catch (error) {
      console.warn(
        "[ShipDGeometry] NURBS evaluation failed, falling back to spline interpolation:",
        error
      );
    }
  }

  // Interpolate sections for smooth rendering if requested
  // Use higher multipliers (3x) for smoother 3D surfaces, especially in Isometric view
  const finalSections = smooth
    ? interpolateSections(sortedSections, stationMultiplier, heightMultiplier)
    : sortedSections;
  const geometry = new THREE.BufferGeometry();
  const vertices: number[] = [];
  const indices: number[] = [];
  const normals: number[] = [];

  let vertexIndex = 0;
  const vertexMap = new Map<string, number>(); // (station, height) -> vertex index

  // First pass: create vertices
  // Three.js coordinate system: X = right/left (starboard/port), Y = up/down (height), Z = forward/back (longitudinal)
  // Center hull at origin: longitudinal from -lpp/2 (aft) to +lpp/2 (forward)
  for (const station of finalSections.stations) {
    // Convert station position (0=aft, 1=forward) to centered Z coordinate
    // 0 -> -lpp/2 (aft), 1 -> +lpp/2 (forward)
    const zRaw = (station.position - 0.5) * lppM; // Center at origin
    if (!Number.isFinite(zRaw)) {
      // Skip invalid station entirely
      continue;
    }
    const z = zRaw;

    // Sort heights for consistent ordering
    const heights = Object.keys(station.offsets)
      .map((h) => Number(h))
      .filter((h) => Number.isFinite(h))
      .sort((a, b) => a - b);

    for (const height of heights) {
      const halfBreadthRaw = station.offsets[height];
      const heightValid = Number.isFinite(height);
      const hbValid = Number.isFinite(halfBreadthRaw);
      if (!heightValid) {
        continue;
      }
      const halfBreadth = hbValid ? Math.max(0, halfBreadthRaw) : 0;

      // At keel (height=0), port and starboard share the same vertex (half-breadth=0)
      if (height === 0 || halfBreadth === 0) {
        const keyKeel = `${station.position}-${height}-keel`;
        if (!vertexMap.has(keyKeel)) {
          vertices.push(0, height, z); // X=0 (centerline), Y=height, Z=longitudinal
          normals.push(0, 1, 0); // Normal pointing up (will be recomputed)
          const keelIndex = vertexIndex++;
          vertexMap.set(keyKeel, keelIndex);
          // Both port and starboard reference the same keel vertex
          vertexMap.set(`${station.position}-${height}-port`, keelIndex);
          vertexMap.set(`${station.position}-${height}-starboard`, keelIndex);
        }
      } else {
        // Port side (negative X)
        const keyPort = `${station.position}-${height}-port`;
        if (!vertexMap.has(keyPort)) {
          vertices.push(-halfBreadth, height, z); // X=port, Y=height, Z=longitudinal
          normals.push(-1, 0, 0); // Normal pointing port (will be recomputed)
          vertexMap.set(keyPort, vertexIndex++);
        }

        // Starboard side (positive X)
        const keyStarboard = `${station.position}-${height}-starboard`;
        if (!vertexMap.has(keyStarboard)) {
          vertices.push(halfBreadth, height, z); // X=starboard, Y=height, Z=longitudinal
          normals.push(1, 0, 0); // Normal pointing starboard (will be recomputed)
          vertexMap.set(keyStarboard, vertexIndex++);
        }
      }
    }

    // Add bulb vertices if present
    if (station.hasBulb && station.bulbOffsets) {
      const bulbHeights = Object.keys(station.bulbOffsets)
        .map((h) => Number(h))
        .filter((h) => Number.isFinite(h))
        .sort((a, b) => a - b);

      for (const height of bulbHeights) {
        const hbRaw = station.bulbOffsets[height];
        if (!Number.isFinite(height) || !Number.isFinite(hbRaw)) {
          continue;
        }
        const halfBreadth = Math.max(0, hbRaw);

        const keyBulbPort = `${station.position}-${height}-bulb-port`;
        if (!vertexMap.has(keyBulbPort)) {
          vertices.push(-halfBreadth, height, z);
          normals.push(-1, 0, 0);
          vertexMap.set(keyBulbPort, vertexIndex++);
        }

        const keyBulbStarboard = `${station.position}-${height}-bulb-starboard`;
        if (!vertexMap.has(keyBulbStarboard)) {
          vertices.push(halfBreadth, height, z);
          normals.push(1, 0, 0);
          vertexMap.set(keyBulbStarboard, vertexIndex++);
        }
      }
    }

    // Add skeg vertices if present
    // Skeg may extend below keel (negative heights)
    if (station.hasSkeg && station.skegOffsets) {
      const skegHeights = Object.keys(station.skegOffsets)
        .map((h) => Number(h))
        .filter((h) => Number.isFinite(h))
        .sort((a, b) => a - b);

      for (const height of skegHeights) {
        const hbRaw = station.skegOffsets[height];
        if (!Number.isFinite(height) || !Number.isFinite(hbRaw)) {
          continue;
        }
        const halfBreadth = Math.max(0, hbRaw);

        // At keel (height=0 or negative), port and starboard may share the same vertex
        if (height <= 0 || halfBreadth === 0) {
          const keyKeel = `${station.position}-${height}-skeg-keel`;
          if (!vertexMap.has(keyKeel)) {
            vertices.push(0, height, z); // X=0 (centerline), Y=height (may be negative), Z=longitudinal
            normals.push(0, 1, 0); // Normal pointing up (will be recomputed)
            const keelIndex = vertexIndex++;
            vertexMap.set(keyKeel, keelIndex);
            // Both port and starboard reference the same keel vertex
            vertexMap.set(`${station.position}-${height}-skeg-port`, keelIndex);
            vertexMap.set(`${station.position}-${height}-skeg-starboard`, keelIndex);
          }
        } else {
          // Port side (negative X)
          const keySkegPort = `${station.position}-${height}-skeg-port`;
          if (!vertexMap.has(keySkegPort)) {
            vertices.push(-halfBreadth, height, z); // X=port, Y=height (may be negative), Z=longitudinal
            normals.push(-1, 0, 0); // Normal pointing port (will be recomputed)
            vertexMap.set(keySkegPort, vertexIndex++);
          }

          // Starboard side (positive X)
          const keySkegStarboard = `${station.position}-${height}-skeg-starboard`;
          if (!vertexMap.has(keySkegStarboard)) {
            vertices.push(halfBreadth, height, z); // X=starboard, Y=height (may be negative), Z=longitudinal
            normals.push(1, 0, 0); // Normal pointing starboard (will be recomputed)
            vertexMap.set(keySkegStarboard, vertexIndex++);
          }
        }
      }
    }
  }

  // Second pass: create faces (connect adjacent stations and heights)
  for (let i = 0; i < finalSections.stations.length - 1; i++) {
    const station1 = finalSections.stations[i];
    const station2 = finalSections.stations[i + 1];

    // Collect all heights from main offsets, bulb offsets, and skeg offsets
    const heights1 = new Set<number>();
    Object.keys(station1.offsets).forEach((h) => {
      const height = Number(h);
      if (Number.isFinite(height)) heights1.add(height);
    });
    if (station1.hasBulb && station1.bulbOffsets) {
      Object.keys(station1.bulbOffsets).forEach((h) => {
        const height = Number(h);
        if (Number.isFinite(height)) heights1.add(height);
      });
    }
    if (station1.hasSkeg && station1.skegOffsets) {
      Object.keys(station1.skegOffsets).forEach((h) => {
        const height = Number(h);
        if (Number.isFinite(height)) heights1.add(height);
      });
    }

    const heights2 = new Set<number>();
    Object.keys(station2.offsets).forEach((h) => {
      const height = Number(h);
      if (Number.isFinite(height)) heights2.add(height);
    });
    if (station2.hasBulb && station2.bulbOffsets) {
      Object.keys(station2.bulbOffsets).forEach((h) => {
        const height = Number(h);
        if (Number.isFinite(height)) heights2.add(height);
      });
    }
    if (station2.hasSkeg && station2.skegOffsets) {
      Object.keys(station2.skegOffsets).forEach((h) => {
        const height = Number(h);
        if (Number.isFinite(height)) heights2.add(height);
      });
    }

    // Match heights (interpolate if needed)
    const allHeights = Array.from(new Set([...heights1, ...heights2]))
      .filter((h) => Number.isFinite(h))
      .sort((a, b) => a - b);

    for (let h = 0; h < allHeights.length - 1; h++) {
      const h1 = allHeights[h];
      const h2 = allHeights[h + 1];

      // Note: Half-breadths are not used in simplified mesh generation
      // The mesh is generated directly from vertex positions stored in vertexMap

      // Helper function to get vertex, checking both regular and skeg vertices
      // CRITICAL: After interpolation, all stations should have identical heights,
      // so exact matching should work. This function handles edge cases (bulb, skeg, keel).
      const getVertex = (
        stationPos: number,
        height: number,
        side: "port" | "starboard"
      ): number | undefined => {
        // Try exact match first (should work after interpolation ensures identical heights)
        let vertex = vertexMap.get(`${stationPos}-${height}-${side}`);
        if (vertex !== undefined) return vertex;

        // Try skeg vertex (for stern extensions below keel)
        vertex = vertexMap.get(`${stationPos}-${height}-skeg-${side}`);
        if (vertex !== undefined) return vertex;

        // Try bulb vertex (for bulbous bow)
        vertex = vertexMap.get(`${stationPos}-${height}-bulb-${side}`);
        if (vertex !== undefined) return vertex;

        // Try keel vertex (for centerline at height=0 or when half-breadth=0)
        if (side === "port" || side === "starboard") {
          vertex = vertexMap.get(`${stationPos}-${height}-keel`);
          if (vertex !== undefined) return vertex;
          vertex = vertexMap.get(`${stationPos}-${height}-skeg-keel`);
          if (vertex !== undefined) return vertex;
        }

        return undefined;
      };

      // Create quad (two triangles) for port side
      const v1_port = getVertex(station1.position, h1, "port");
      const v2_port = getVertex(station1.position, h2, "port");
      const v3_port = getVertex(station2.position, h1, "port");
      const v4_port = getVertex(station2.position, h2, "port");

      if (
        v1_port !== undefined &&
        v2_port !== undefined &&
        v3_port !== undefined &&
        v4_port !== undefined
      ) {
        indices.push(v1_port, v2_port, v3_port);
        indices.push(v2_port, v4_port, v3_port);
      }

      // Create quad for starboard side
      const v1_starboard = getVertex(station1.position, h1, "starboard");
      const v2_starboard = getVertex(station1.position, h2, "starboard");
      const v3_starboard = getVertex(station2.position, h1, "starboard");
      const v4_starboard = getVertex(station2.position, h2, "starboard");

      if (
        v1_starboard !== undefined &&
        v2_starboard !== undefined &&
        v3_starboard !== undefined &&
        v4_starboard !== undefined
      ) {
        indices.push(v1_starboard, v3_starboard, v2_starboard);
        indices.push(v2_starboard, v3_starboard, v4_starboard);
      }
    }
  }

  // Helper function to get vertex for closing faces (checks regular, bulb, and skeg)
  const getClosingVertex = (
    stationPos: number,
    height: number,
    side: "port" | "starboard"
  ): number | undefined => {
    // Try regular vertex first
    let vertex = vertexMap.get(`${stationPos}-${height}-${side}`);
    if (vertex !== undefined) return vertex;

    // Try bulb vertex (for bow)
    vertex = vertexMap.get(`${stationPos}-${height}-bulb-${side}`);
    if (vertex !== undefined) return vertex;

    // Try skeg vertex (for stern)
    vertex = vertexMap.get(`${stationPos}-${height}-skeg-${side}`);
    if (vertex !== undefined) return vertex;

    // Try keel vertex (for centerline)
    vertex = vertexMap.get(`${stationPos}-${height}-keel`);
    if (vertex !== undefined) return vertex;
    vertex = vertexMap.get(`${stationPos}-${height}-skeg-keel`);
    if (vertex !== undefined) return vertex;

    return undefined;
  };

  // Add closing faces at bow (position = 1, forward end)
  const bowStation = finalSections.stations.find((s) => Math.abs(s.position - 1.0) < 0.01);
  if (bowStation) {
    // Collect all heights from main offsets and bulb offsets
    const bowHeights = new Set<number>();
    Object.keys(bowStation.offsets).forEach((h) => {
      const height = Number(h);
      if (Number.isFinite(height)) bowHeights.add(height);
    });
    if (bowStation.hasBulb && bowStation.bulbOffsets) {
      Object.keys(bowStation.bulbOffsets).forEach((h) => {
        const height = Number(h);
        if (Number.isFinite(height)) bowHeights.add(height);
      });
    }
    const sortedBowHeights = Array.from(bowHeights).sort((a, b) => a - b);

    // Close bow end (create pointed tip)
    // At the bow tip (position = 1.0), the longitudinal taper should make half-breadth = 0
    // All points should converge at the centerline, creating a sharp pointed bow
    // If half-breadth > 0, we create a closing face; if = 0, all vertices are at centerline (single point)
    for (let h = 0; h < sortedBowHeights.length - 1; h++) {
      const h1 = sortedBowHeights[h];
      const h2 = sortedBowHeights[h + 1];

      // Try to get vertices (may be at centerline if half-breadth = 0)
      const v1_keel = vertexMap.get(`${bowStation.position}-${h1}-keel`);
      const v2_keel = vertexMap.get(`${bowStation.position}-${h2}-keel`);
      const v1_port = getClosingVertex(bowStation.position, h1, "port");
      const v2_port = getClosingVertex(bowStation.position, h2, "port");
      const v1_starboard = getClosingVertex(bowStation.position, h1, "starboard");
      const v2_starboard = getClosingVertex(bowStation.position, h2, "starboard");

      // Check if port and starboard are the same (converged at centerline)
      const isAtCenterline1 = v1_port === v1_starboard || v1_keel !== undefined;
      const isAtCenterline2 = v2_port === v2_starboard || v2_keel !== undefined;

      if (isAtCenterline1 && isAtCenterline2) {
        // Both heights are at centerline (half-breadth = 0) - bow tip is a point
        // No closing face needed, the hull already converges to a point
        continue;
      } else if (isAtCenterline1) {
        // Lower height is at centerline - create triangles from centerline point
        const centerVertex = v1_keel || v1_port || v1_starboard;
        if (centerVertex !== undefined && v2_port !== undefined && v2_starboard !== undefined) {
          indices.push(centerVertex, v2_port, v2_starboard);
        }
      } else if (isAtCenterline2) {
        // Upper height is at centerline - create triangles converging to centerline
        const centerVertex = v2_keel || v2_port || v2_starboard;
        if (centerVertex !== undefined && v1_port !== undefined && v1_starboard !== undefined) {
          indices.push(v1_port, v1_starboard, centerVertex);
        }
      } else if (
        v1_port !== undefined &&
        v2_port !== undefined &&
        v1_starboard !== undefined &&
        v2_starboard !== undefined
      ) {
        // Standard case: port and starboard are separate (half-breadth > 0)
        // Create quad closing the bow end
        indices.push(v1_port, v1_starboard, v2_port);
        indices.push(v2_port, v1_starboard, v2_starboard);
      }
    }
  }

  // Add closing faces at stern (position = 0, aft end)
  const sternStation = finalSections.stations.find((s) => Math.abs(s.position - 0.0) < 0.01);
  if (sternStation) {
    // Collect all heights from main offsets and skeg offsets (skeg may extend below keel)
    const sternHeights = new Set<number>();
    Object.keys(sternStation.offsets).forEach((h) => {
      const height = Number(h);
      if (Number.isFinite(height)) sternHeights.add(height);
    });
    if (sternStation.hasSkeg && sternStation.skegOffsets) {
      Object.keys(sternStation.skegOffsets).forEach((h) => {
        const height = Number(h);
        if (Number.isFinite(height)) sternHeights.add(height);
      });
    }
    const sortedSternHeights = Array.from(sternHeights).sort((a, b) => a - b);

    // Close stern end - handle both transom (flat face) and canoe (pointed) stern types
    // Transom stern: Maintains width at stern tip -> flat closing face (correct)
    // Canoe/cruiser stern: Tapers to zero width -> converge to point (like bow)

    // Check if stern has width (transom) or converges to point (canoe)
    // If all heights have separate port/starboard vertices, it's a transom (flat face)
    // If vertices converge to centerline (half-breadth = 0), it's canoe (pointed)
    let hasSternWidth = false;
    for (const height of sortedSternHeights) {
      const v_port = getClosingVertex(sternStation.position, height, "port");
      const v_starboard = getClosingVertex(sternStation.position, height, "starboard");
      if (v_port !== undefined && v_starboard !== undefined && v_port !== v_starboard) {
        hasSternWidth = true;
        break;
      }
    }

    for (let h = 0; h < sortedSternHeights.length - 1; h++) {
      const h1 = sortedSternHeights[h];
      const h2 = sortedSternHeights[h + 1];

      const v1_port = getClosingVertex(sternStation.position, h1, "port");
      const v2_port = getClosingVertex(sternStation.position, h2, "port");
      const v1_starboard = getClosingVertex(sternStation.position, h1, "starboard");
      const v2_starboard = getClosingVertex(sternStation.position, h2, "starboard");
      const v1_keel = vertexMap.get(`${sternStation.position}-${h1}-keel`);
      const v2_keel = vertexMap.get(`${sternStation.position}-${h2}-keel`);

      // Check if vertices are at centerline (half-breadth = 0)
      const isAtCenterline1 = v1_port === v1_starboard || v1_keel !== undefined;
      const isAtCenterline2 = v2_port === v2_starboard || v2_keel !== undefined;

      if (hasSternWidth && !isAtCenterline1 && !isAtCenterline2) {
        // TRANSOM STERN: Create flat closing face (port and starboard are separate)
        if (
          v1_port !== undefined &&
          v2_port !== undefined &&
          v1_starboard !== undefined &&
          v2_starboard !== undefined
        ) {
          // Stern closing face (two triangles forming a quad)
          indices.push(v1_starboard, v1_port, v2_starboard);
          indices.push(v2_starboard, v1_port, v2_port);
        }
      } else if (!hasSternWidth || isAtCenterline1 || isAtCenterline2) {
        // CANOE/CRUISER STERN: Handle convergence to point (similar to bow)
        if (isAtCenterline1 && isAtCenterline2) {
          // Both heights at centerline - stern tip is a point
          continue;
        } else if (isAtCenterline1) {
          // Lower height at centerline - create triangles converging to point
          const centerVertex = v1_keel || v1_port || v1_starboard;
          if (centerVertex !== undefined && v2_port !== undefined && v2_starboard !== undefined) {
            indices.push(centerVertex, v2_starboard, v2_port);
          }
        } else if (isAtCenterline2) {
          // Upper height at centerline - create triangles converging to point
          const centerVertex = v2_keel || v2_port || v2_starboard;
          if (centerVertex !== undefined && v1_port !== undefined && v1_starboard !== undefined) {
            indices.push(v1_starboard, v1_port, centerVertex);
          }
        }
      }
    }
  }

  // Add bottom closing face (keel) - connect all stations at height=0
  // At keel (height=0), port and starboard share the same vertex (half-breadth=0)
  const keelVertices: number[] = [];
  for (const station of finalSections.stations) {
    // At height=0, both port and starboard reference the same keel vertex
    const keelVertex =
      vertexMap.get(`${station.position}-0-keel`) ||
      vertexMap.get(`${station.position}-0-port`) ||
      vertexMap.get(`${station.position}-0-starboard`);
    if (keelVertex !== undefined && !keelVertices.includes(keelVertex)) {
      keelVertices.push(keelVertex);
    }
  }

  // Create bottom face by connecting keel vertices along the longitudinal axis
  if (keelVertices.length >= 3) {
    // Sort by Z coordinate (longitudinal position: aft to forward)
    const sortedKeelVertices = keelVertices.sort((a, b) => {
      const za = vertices[a * 3 + 2]; // Z coordinate (longitudinal)
      const zb = vertices[b * 3 + 2];
      return za - zb;
    });

    // Create triangles along the keel (forming a continuous bottom surface)
    for (let i = 0; i < sortedKeelVertices.length - 2; i++) {
      indices.push(sortedKeelVertices[i], sortedKeelVertices[i + 1], sortedKeelVertices[i + 2]);
    }
  }

  geometry.setAttribute("position", new THREE.Float32BufferAttribute(vertices, 3));
  geometry.setAttribute("normal", new THREE.Float32BufferAttribute(normals, 3));
  geometry.setIndex(indices);
  // Defensive: if any NaN sneaks in, avoid crashing renderer
  const posArr = geometry.getAttribute("position") as THREE.BufferAttribute;
  let hasNaN = false;
  {
    const arr = posArr.array as unknown as number[];
    for (let i = 0; i < arr.length; i++) {
      if (!Number.isFinite(arr[i])) {
        hasNaN = true;
        break;
      }
    }
  }
  if (hasNaN) {
    console.warn(
      "[ShipD] Invalid hull geometry detected (NaN positions). Returning empty geometry."
    );
    return new THREE.BufferGeometry();
  }
  geometry.computeVertexNormals();

  return geometry;
}

// Note: getHalfBreadthAtHeight function removed - not used in simplified mesh generation
// Can be re-added if needed for more sophisticated mesh generation

/**
 * Denormalizes ShipD parameters from 0-1 range to physical units
 */
function denormalizeParameters(
  shipdVector: number[],
  metadata: ShipDParameterMetadata[]
): Record<number, number> {
  const denormalized: Record<number, number> = {};

  for (let i = 0; i < shipdVector.length; i++) {
    const param = metadata.find((m) => m.parameterIndex === i);
    const normalized = shipdVector[i];

    if (param && param.min != null && param.max != null) {
      // Linear denormalization: physical = min + (max - min) * normalized
      const physical = param.min + (param.max - param.min) * normalized;
      denormalized[i] = physical;
    } else {
      // No metadata - use normalized value as-is
      denormalized[i] = normalized;
    }
  }

  return denormalized;
}

/**
 * Generates offsets for a single station based on ShipD parameters
 */
function generateStationOffsets(
  stationPos: number,
  region: "bow" | "midship" | "stern",
  denormalized: Record<number, number>,
  shipdVector: number[],
  _lppM: number,
  beamM: number,
  draftM: number,
  _metadata: ShipDParameterMetadata[]
): Record<number, number> {
  const offsets: Record<number, number> = {};

  // === DEFENSIVE VALIDATION ===
  // Validate all critical inputs before ANY calculations to prevent NaN propagation
  if (!Number.isFinite(beamM) || beamM <= 0) {
    console.error("[ShipD generateStationOffsets] Invalid beam:", beamM);
    offsets[0] = 0; // Return minimal valid offsets (centerline only)
    return offsets;
  }
  if (!Number.isFinite(draftM) || draftM <= 0) {
    console.error("[ShipD generateStationOffsets] Invalid draft:", draftM);
    offsets[0] = 0;
    return offsets;
  }
  if (!Number.isFinite(stationPos)) {
    console.error("[ShipD generateStationOffsets] Invalid station position:", stationPos);
    offsets[0] = 0;
    return offsets;
  }

  // Validate denormalized parameters (replace with safe versions)
  const validatedDenormalized: Record<number, number> = {};
  for (const key in denormalized) {
    const value = denormalized[key];
    validatedDenormalized[key] = Number.isFinite(value) ? value : 0;
  }
  denormalized = validatedDenormalized; // Reassign to use validated values throughout

  // Validate ShipD vector (replace with safe versions)
  const validatedShipdVector: number[] = [];
  for (let i = 0; i < shipdVector.length; i++) {
    const value = shipdVector[i];
    validatedShipdVector[i] = Number.isFinite(value) ? value : 0;
  }
  shipdVector = validatedShipdVector; // Reassign to use validated values throughout

  // Always start with keel point (height=0, half-breadth=0) to close the bottom
  offsets[0] = 0;

  // Generate offsets at various heights (including freeboard above waterline)
  const heightSteps = 20;
  const maxHeight = draftM * 1.35; // Include 35% freeboard above waterline (more realistic proportions)

  for (let h = 1; h <= heightSteps; h++) {
    // Start from 1 to avoid duplicate keel point
    const height = (h / heightSteps) * maxHeight; // Height from keel to above waterline

    let halfBreadth = 0;

    if (region === "bow") {
      // Bow section: use Beta (flare), Cdrft (deadrise), Rc (curvature), Rk (knuckle), Kappa_bow (convex/concave)
      const beta = denormalized[8]; // Flare angle (degrees)
      // PHASE 2: R_c (curvature) parameter: Use full 0-1 range for dramatic shape variation
      // Rc controls section curvature: 0 = very curved/fine, 1 = very straight/full
      const rcNorm = shipdVector[9] ?? 0; // Curvature coefficient (normalized 0-1)
      const rc = rcNorm <= 0 ? 0.3 : rcNorm; // Use full 0-1 range, default 0.3 if zero/negative
      // PHASE 2: Enforce R_k (knuckle) parameter: 0.1-0.3 normalized for deck edge transition
      // Fix: Set to moderate positive value (0.1-0.3) to introduce gentle radius and ensure continuity
      const rkNorm = shipdVector[10] ?? 0; // Knuckle coefficient (normalized 0-1)
      const rk = rkNorm <= 0 ? 0.2 : Math.max(0.1, Math.min(0.3, rkNorm)); // Default 0.2 if zero/negative
      const kappaBow = denormalized[14]; // Curvature type (-1 to 1, concave to convex)
      const cdrft = denormalized[19]; // Deadrise angle (degrees)

      // PHASE 2: Detect chine type from Rc parameter
      // Soft chine: Rc > 0.6 (rounder bilge, fuller curvature)
      // Hard chine: Rc <= 0.6 (sharper, more angular)
      const chineType = rc > 0.6 ? "soft" : "hard";

      const heightRatio = height / draftM;

      // CORRECT VERTICAL PROFILE: Narrow at keel, wide at waterline
      // CRITICAL: Calculate waterline half-breadth first to ensure smooth transition
      let waterlineHalfBreadth = 0;

      if (height <= draftM) {
        // BELOW WATERLINE: Expand from narrow keel to wide waterline
        let baseHalfBreadth = 0;

        if (chineType === "soft") {
          // PHASE 2: SOFT CHINE - FLAT BOTTOM
          // Soft chine has a FLAT bottom (not V-shaped) with rounded bilge transition
          // The flat bottom extends horizontally from near the keel (for numerical stability, start at 0.01m)
          const flatBottomStartHeight = 0.01; // Start flat bottom slightly above keel for numerical stability
          const flatBottomHeight = draftM * 0.3; // Flat for 30% of draft

          if (height <= flatBottomStartHeight) {
            // At keel: half-breadth = 0 (centerline)
            baseHalfBreadth = 0;
          } else if (height <= flatBottomHeight) {
            // FLAT BOTTOM: Constant half-breadth (horizontal flat section)
            const flatBottomHalfBreadth = (beamM / 2) * 0.4; // 40% of max beam at flat bottom
            baseHalfBreadth = flatBottomHalfBreadth;
          } else {
            // ROUNDED BILGE: Smooth curve from flat bottom to waterline
            const bilgeRatio = (height - flatBottomHeight) / (draftM - flatBottomHeight);
            const curvePower = 2.0 + rc * 0.5; // Rc affects roundness (higher Rc = rounder)
            const expansionRatio = Math.pow(bilgeRatio, 1 / curvePower);

            const flatBottomHalfBreadth = (beamM / 2) * 0.4;
            const waterlineHalfBreadthTarget = beamM / 2;
            baseHalfBreadth =
              flatBottomHalfBreadth +
              (waterlineHalfBreadthTarget - flatBottomHalfBreadth) * expansionRatio;
          }
          // NO KNUCKLE for soft chine (smooth transition, no sharp angles)
        } else {
          // HARD CHINE - V-SHAPE (existing logic, but ensure keel = 0)
          // 1. Calculate keel width (reduced by deadrise)
          const deadriseReduction = Math.tan((cdrft * Math.PI) / 180) * (draftM - height);
          const keelHalfBreadth = 0; // True point at keel for hard chine

          // 2. Expansion curve from keel to waterline
          // Higher Rc = fuller (straighter expansion), Lower Rc = finer (more curved)
          const curvePower = 2.5 - rc * 1.5; // Range: 1.0 (full) to 2.5 (fine)
          const expansionRatio = Math.pow(heightRatio, 1 / curvePower);

          // 3. Interpolate from keel to max beam
          baseHalfBreadth =
            keelHalfBreadth +
            (beamM / 2 - keelHalfBreadth - deadriseReduction * 0.3) * expansionRatio;

          // 4. Apply knuckle effect with proper R_k radius (0.1-0.3)
          // R_k now always has a valid value (enforced above), so always apply
          const knuckleHeight = 0.5; // Knuckle at mid-height
          const knuckleRange = 0.2;
          if (Math.abs(heightRatio - knuckleHeight) < knuckleRange) {
            const knuckleFactor = 1 - Math.abs(heightRatio - knuckleHeight) / knuckleRange;
            // Scale knuckle effect by R_k value (0.1-0.3 range, normalized to 0-1)
            const knuckleEffect = (rk - 0.1) / 0.2; // Normalize 0.1-0.3 to 0-1
            baseHalfBreadth *= 1 + knuckleEffect * knuckleFactor * 0.15;
          }
        }

        // 5. Apply convex/concave control (for both soft and hard chine)
        if (Math.abs(kappaBow) > 0.1) {
          const convexEffect = kappaBow * Math.sin((heightRatio * Math.PI) / 2) * 0.1;
          baseHalfBreadth *= 1 + convexEffect;
        }

        halfBreadth = Math.max(0, baseHalfBreadth);

        // Store waterline half-breadth for smooth above-waterline transition
        if (Math.abs(height - draftM) < 0.001) {
          waterlineHalfBreadth = halfBreadth;
        }
      } else {
        // ABOVE WATERLINE: Apply flare (widen) with smooth transition
        const aboveWLHeight = height - draftM;
        const freeboard = draftM * 0.35; // 35% freeboard above waterline
        const aboveWLRatio = Math.min(aboveWLHeight / freeboard, 1.0);

        // CRITICAL: Use actual waterline half-breadth from below-waterline calculation
        // If not available, calculate it at waterline (height = draftM)
        if (waterlineHalfBreadth === 0) {
          // Calculate waterline half-breadth using same logic as below-waterline
          if (chineType === "soft") {
            // Soft chine: waterline is at end of rounded bilge transition
            const flatBottomHeight = draftM * 0.3;
            const bilgeRatio = (draftM - flatBottomHeight) / (draftM - flatBottomHeight); // = 1.0 at waterline
            const curvePower = 2.0 + rc * 0.5;
            const expansionRatio = Math.pow(bilgeRatio, 1 / curvePower); // = 1.0
            const flatBottomHalfBreadth = (beamM / 2) * 0.4;
            const waterlineHalfBreadthTarget = beamM / 2;
            waterlineHalfBreadth =
              flatBottomHalfBreadth +
              (waterlineHalfBreadthTarget - flatBottomHalfBreadth) * expansionRatio;
          } else {
            // Hard chine: use V-shape logic
            const keelHalfBreadth = 0;
            const curvePower = 2.5 - rc * 1.5;
            const expansionRatio = Math.pow(1.0, 1 / curvePower); // heightRatio = 1.0 at waterline
            const deadriseReduction = 0; // At waterline, no deadrise reduction
            waterlineHalfBreadth =
              keelHalfBreadth +
              (beamM / 2 - keelHalfBreadth - deadriseReduction * 0.3) * expansionRatio;

            // Apply knuckle and convex/concave effects at waterline
            // R_k now always has a valid value (enforced above), so always apply
            const knuckleHeight = 0.5;
            const knuckleRange = 0.2;
            if (Math.abs(1.0 - knuckleHeight) < knuckleRange) {
              const knuckleFactor = 1 - Math.abs(1.0 - knuckleHeight) / knuckleRange;
              // Scale knuckle effect by R_k value (0.1-0.3 range, normalized to 0-1)
              const knuckleEffect = (rk - 0.1) / 0.2; // Normalize 0.1-0.3 to 0-1
              waterlineHalfBreadth *= 1 + knuckleEffect * knuckleFactor * 0.15;
            }
          }
          // Apply convex/concave control at waterline (for both soft and hard chine)
          if (Math.abs(kappaBow) > 0.1) {
            const convexEffect = kappaBow * Math.sin((1.0 * Math.PI) / 2) * 0.1;
            waterlineHalfBreadth *= 1 + convexEffect;
          }
        }

        // Start at actual waterline half-breadth (ensures continuity)
        let baseHalfBreadth = waterlineHalfBreadth;

        // Add flare effect with smooth transition
        if (beta > 5) {
          // Use smooth flare curve to avoid abrupt changes
          const flareExpansion = Math.tan((beta * Math.PI) / 180) * aboveWLHeight;
          // Apply gradual flare increase (smooth curve, not linear)
          const flareCurve = Math.pow(aboveWLRatio, 1.5); // Smooth curve
          baseHalfBreadth += flareExpansion * 0.2 * flareCurve;
        }

        // Ensure monotonicity: above-waterline should be >= waterline
        halfBreadth = Math.max(waterlineHalfBreadth, baseHalfBreadth);
      }
    } else if (region === "midship") {
      // Midship section: Check for deep_v_midship (yacht) vs standard midship
      // Deep V midship uses: Adrft (17), Bdrft (18), Cdrft (19)
      // Standard midship uses: bit_EP_S (20), bit_EP_T (21)

      // Detect deep V midship: Cdrft (deadrise angle) > 20 degrees indicates deep V
      const cdrft = denormalized[19]; // Deadrise angle (degrees)
      const isDeepV = cdrft > 20; // Deep V midship typically has higher deadrise

      const heightRatio = height / draftM;

      // CORRECT VERTICAL PROFILE: Midship typically parallel below waterline
      // CRITICAL: Calculate waterline half-breadth first to ensure smooth transition
      let waterlineHalfBreadth = 0;

      if (height <= draftM) {
        // BELOW WATERLINE
        if (isDeepV) {
          // DEEP V MIDSHIP (yacht): Use Bdrft, Cdrft for deadrise control
          const bdrft = denormalized[18]; // Draft rocker coefficient B

          // Deep V has more deadrise (narrower keel, wider at waterline)
          // Cdrft controls the deadrise angle directly
          const deadriseAngle = cdrft; // Already in degrees
          const deadriseReduction = Math.tan((deadriseAngle * Math.PI) / 180) * (draftM - height);

          // Keel width is narrower for deep V (more deadrise)
          const keelHalfBreadth = 0.01; // Deep V keel closes at centerline (1cm for numerical stability)

          // Expansion curve with deadrise effect
          // Bdrft affects the curve shape
          const curvePower = 1.5 - bdrft * 0.5; // Range: 1.0-1.5 (more V-shaped)
          const expansionRatio = Math.pow(heightRatio, 1 / curvePower);

          const baseHalfBreadth =
            keelHalfBreadth +
            (beamM / 2 - keelHalfBreadth - deadriseReduction * 0.2) * expansionRatio;

          halfBreadth = Math.max(0, baseHalfBreadth);

          // Store waterline half-breadth for smooth above-waterline transition
          if (Math.abs(height - draftM) < 0.001) {
            waterlineHalfBreadth = halfBreadth;
          }
        } else {
          // STANDARD MIDSHIP: Gentle expansion from keel to waterline
          // Midship has less deadrise, more parallel sides
          const keelHalfBreadth = 0.01; // Keel closes at centerline (1cm for numerical stability)

          // Simple gentle expansion (midship is typically straighter)
          const expansionRatio = Math.pow(heightRatio, 0.8); // Gentle curve
          const baseHalfBreadth = keelHalfBreadth + (beamM / 2 - keelHalfBreadth) * expansionRatio;

          halfBreadth = baseHalfBreadth;

          // Store waterline half-breadth for smooth above-waterline transition
          if (Math.abs(height - draftM) < 0.001) {
            waterlineHalfBreadth = halfBreadth;
          }
        }
      } else {
        // ABOVE WATERLINE: Smooth transition from waterline
        const aboveWLHeight = height - draftM;
        const freeboard = draftM * 0.35; // Match total freeboard (35%)
        const aboveWLRatio = Math.min(aboveWLHeight / freeboard, 1.0);

        // CRITICAL: Use actual waterline half-breadth from below-waterline calculation
        if (waterlineHalfBreadth === 0) {
          // Calculate waterline half-breadth using same logic as below-waterline
          if (isDeepV) {
            const bdrft = denormalized[18];
            const keelHalfBreadth = 0.01;
            const curvePower = 1.5 - bdrft * 0.5;
            const expansionRatio = Math.pow(1.0, 1 / curvePower); // heightRatio = 1.0 at waterline
            waterlineHalfBreadth = keelHalfBreadth + (beamM / 2 - keelHalfBreadth) * expansionRatio;
          } else {
            const keelHalfBreadth = 0.01;
            const expansionRatio = Math.pow(1.0, 0.8); // heightRatio = 1.0 at waterline
            waterlineHalfBreadth = keelHalfBreadth + (beamM / 2 - keelHalfBreadth) * expansionRatio;
          }
        }

        // Start at actual waterline half-breadth (ensures continuity)
        let baseHalfBreadth = waterlineHalfBreadth;

        if (isDeepV) {
          // Deep V midship: Use Adrft/Bdrft for sheer effects above waterline
          const adrft = denormalized[17];
          const bdrft = denormalized[18];

          // Adrft affects outward curve (sheer)
          if (adrft > 0 && aboveWLRatio > 0.5) {
            baseHalfBreadth *= 1 + adrft * ((aboveWLRatio - 0.5) / 0.5) * 0.05;
          }

          // Bdrft affects inward curve (tumblehome)
          if (bdrft < 0 && aboveWLRatio > 0.5) {
            baseHalfBreadth *= 1 + bdrft * ((aboveWLRatio - 0.5) / 0.5) * 0.05;
          }
        } else {
          // STANDARD MIDSHIP: Use bit_EP_S (sheer), bit_EP_T (tumblehome)
          const bitEPS = denormalized[20] > 0.5; // Sheer extrusion
          const bitEPT = denormalized[21] > 0.5; // Tumblehome

          // Sheer (outward curve at deck)
          if (bitEPS && aboveWLRatio > 0.6) {
            baseHalfBreadth *= 1 + ((aboveWLRatio - 0.6) / 0.4) * 0.08;
          }

          // Tumblehome (inward curve at deck)
          if (bitEPT && aboveWLRatio > 0.5) {
            baseHalfBreadth *= 1 - ((aboveWLRatio - 0.5) / 0.5) * 0.15;
          }
        }

        halfBreadth = baseHalfBreadth;
      }
    } else {
      // Stern section: Detect transom_stern vs canoe_stern from Atrans parameter
      // Transom stern uses: Atrans, Beta_trans, Bc_trans, Rc_trans, Rk_trans, Kappa_stern
      // Canoe stern uses: Adel_stern (25), Bdel_stern (26)

      // CRITICAL: Use normalized vector for family detection (consistent with backend)
      const atransNorm = shipdVector[22] ?? 0; // Transom area coefficient (normalized 0-1)
      const isTransomStern = atransNorm > 0.5; // Transom when > 0.5, canoe when <= 0.5

      const kappaStern = denormalized[24]; // Curvature type (-1 to 1, concave to convex)
      const betaTrans = denormalized[27]; // Stern rake angle
      const bcTrans = denormalized[28]; // Transom width ratio
      // PHASE 2: R_c (curvature) for stern: Use full 0-1 range for dramatic shape variation
      // Rc_trans controls stern curvature: 0 = very curved/fine, 1 = very straight/full
      const rcTransNorm = shipdVector[29] ?? 0; // Stern curvature coefficient (normalized 0-1)
      const rcTrans = rcTransNorm <= 0 ? 0.3 : rcTransNorm; // Use full 0-1 range, default 0.3 if zero/negative
      // PHASE 2: Enforce R_k (knuckle) for stern: 0.0-0.2 normalized
      // Fix: Set to 0.0 or slightly positive to define sheer line knuckle smoothly
      const rkTransNorm = shipdVector[30] ?? 0; // Stern knuckle coefficient (normalized 0-1)
      const rkTrans = rkTransNorm <= 0 ? 0.1 : Math.max(0.0, Math.min(0.2, rkTransNorm)); // Default 0.1 if zero/negative
      const adelStern = denormalized[25]; // Canoe stern sheer coefficient A
      const bdelStern = denormalized[26]; // Canoe stern sheer coefficient B

      const heightRatio = height / draftM;

      // CORRECT VERTICAL PROFILE: Similar to bow but with stern characteristics
      // CRITICAL: Calculate waterline half-breadth first to ensure smooth transition
      let waterlineHalfBreadth = 0;

      if (height <= draftM) {
        // BELOW WATERLINE: Expand from narrow keel to wide waterline
        const keelHalfBreadth = 0.01; // Stern keel closes at centerline (1cm for numerical stability)

        if (isTransomStern) {
          // TRANSOM STERN: Use transom parameters
          const atrans = denormalized[22];

          // Curvature expansion
          const curvePower = 2.5 - rcTrans * 1.5; // Range: 1.0 (full) to 2.5 (fine)
          const expansionRatio = Math.pow(heightRatio, 1 / curvePower);

          let baseHalfBreadth = keelHalfBreadth + (beamM / 2 - keelHalfBreadth) * expansionRatio;

          // Transom effect (flat stern) - only near the very aft
          if (stationPos < 0.15 && atrans > 0.5) {
            const transomWidth = beamM * bcTrans;
            const transomBlend = (0.15 - stationPos) / 0.15; // Blend over aft 15%
            baseHalfBreadth =
              baseHalfBreadth * (1 - transomBlend * atrans) +
              (transomWidth / 2) * transomBlend * atrans;
          }

          // PHASE 2: Apply stern knuckle with proper R_k radius (0.0-0.2)
          // R_k now always has a valid value, so always apply if in range
          if (heightRatio > 0.3 && heightRatio < 0.6) {
            const knuckleFactor = 1 - Math.abs(heightRatio - 0.45) / 0.15;
            // Scale knuckle effect by R_k value (0.0-0.2 range, normalized to 0-1)
            const knuckleEffect = (rkTrans - 0.0) / 0.2; // Normalize 0.0-0.2 to 0-1
            baseHalfBreadth *= 1 + knuckleEffect * knuckleFactor * 0.12;
          }

          // Apply convex/concave control
          if (Math.abs(kappaStern) > 0.1) {
            const convexEffect = kappaStern * Math.sin((heightRatio * Math.PI) / 2) * 0.1;
            baseHalfBreadth *= 1 + convexEffect;
          }

          halfBreadth = Math.max(0, baseHalfBreadth);

          // Store waterline half-breadth for smooth above-waterline transition
          if (Math.abs(height - draftM) < 0.001) {
            waterlineHalfBreadth = halfBreadth;
          }
        } else {
          // CANOE STERN (yacht): Use Adel_stern, Bdel_stern for rounded stern shape
          // Canoe stern has more rounded, elliptical sections (less V-shaped)

          // Curvature expansion - canoe stern is more rounded (higher power)
          const curvePower = 2.0 + rcTrans * 1.0; // Range: 2.0-3.0 (more rounded)
          const expansionRatio = Math.pow(heightRatio, 1 / curvePower);

          let baseHalfBreadth = keelHalfBreadth + (beamM / 2 - keelHalfBreadth) * expansionRatio;

          // Adel_stern and Bdel_stern affect the stern curvature
          // Adel_stern: affects the vertical curvature (sheer)
          // Bdel_stern: affects the horizontal curvature (roundness)
          if (Math.abs(adelStern) > 0.1) {
            const adelEffect = adelStern * Math.sin(heightRatio * Math.PI) * 0.1;
            baseHalfBreadth *= 1 + adelEffect;
          }

          if (Math.abs(bdelStern) > 0.1) {
            const bdelEffect = bdelStern * Math.cos((heightRatio * Math.PI) / 2) * 0.08;
            baseHalfBreadth *= 1 + bdelEffect;
          }

          // Apply convex/concave control (less pronounced for canoe stern)
          if (Math.abs(kappaStern) > 0.1) {
            const convexEffect = kappaStern * Math.sin((heightRatio * Math.PI) / 2) * 0.05; // Reduced effect
            baseHalfBreadth *= 1 + convexEffect;
          }

          halfBreadth = Math.max(0, baseHalfBreadth);

          // Store waterline half-breadth for smooth above-waterline transition
          if (Math.abs(height - draftM) < 0.001) {
            waterlineHalfBreadth = halfBreadth;
          }
        }
      } else {
        // ABOVE WATERLINE: Smooth transition from waterline
        const aboveWLHeight = height - draftM;

        // CRITICAL: Use actual waterline half-breadth from below-waterline calculation
        if (waterlineHalfBreadth === 0) {
          // Calculate waterline half-breadth using same logic as below-waterline
          const keelHalfBreadth = 0.01;
          if (isTransomStern) {
            const curvePower = 2.5 - rcTrans * 1.5;
            const expansionRatio = Math.pow(1.0, 1 / curvePower); // heightRatio = 1.0 at waterline
            waterlineHalfBreadth = keelHalfBreadth + (beamM / 2 - keelHalfBreadth) * expansionRatio;
            // Apply transom effect at waterline if in transom region
            const atrans = denormalized[22];
            if (stationPos < 0.15 && atrans > 0.5) {
              const transomWidth = beamM * bcTrans;
              const transomBlend = (0.15 - stationPos) / 0.15;
              waterlineHalfBreadth =
                waterlineHalfBreadth * (1 - transomBlend * atrans) +
                (transomWidth / 2) * transomBlend * atrans;
            }
          } else {
            const curvePower = 2.0 + rcTrans * 1.0;
            const expansionRatio = Math.pow(1.0, 1 / curvePower); // heightRatio = 1.0 at waterline
            waterlineHalfBreadth = keelHalfBreadth + (beamM / 2 - keelHalfBreadth) * expansionRatio;
          }
        }

        // Start at actual waterline half-breadth (ensures continuity)
        let baseHalfBreadth = waterlineHalfBreadth;

        if (isTransomStern) {
          // TRANSOM STERN: Apply rake (aft overhang)
          if (betaTrans > 5 && stationPos < 0.2) {
            const rakeExpansion = Math.tan((betaTrans * Math.PI) / 180) * aboveWLHeight;
            baseHalfBreadth += rakeExpansion * 0.15;
          }
        } else {
          // CANOE STERN: Use Adel_stern/Bdel_stern for sheer effects above waterline
          const freeboard = draftM * 0.35;
          const aboveWLRatio = Math.min(aboveWLHeight / freeboard, 1.0);

          // Adel_stern affects outward curve (sheer) above waterline
          if (adelStern > 0 && aboveWLRatio > 0.4) {
            baseHalfBreadth *= 1 + adelStern * ((aboveWLRatio - 0.4) / 0.6) * 0.08;
          }

          // Bdel_stern affects inward curve (tumblehome) above waterline
          if (bdelStern < 0 && aboveWLRatio > 0.5) {
            baseHalfBreadth *= 1 + bdelStern * ((aboveWLRatio - 0.5) / 0.5) * 0.1;
          }
        }

        halfBreadth = Math.max(0, baseHalfBreadth);
      }
    }

    // LONGITUDINAL SCALING: Apply taper based on station position, region, and hull family
    // This creates the actual bow/stern taper (hull narrows toward ends)
    // CRITICAL: Different stern families require different taper profiles to avoid incorrect V-shapes
    let longitudinalScale = 1.0;

    if (region === "bow") {
      // Bow region: Taper from full beam at bowStart to centerline at bow tip (pos=1.0)
      // Need bow boundaries - use vector directly (already ratios)
      const lb = shipdVector[1] ?? 0.3; // Bow length ratio
      const ls = shipdVector[2] ?? 0.3; // Stern length ratio
      const bowStart = 1.0 - lb - ls + ls; // Start of bow region

      if (stationPos >= bowStart) {
        // Position within bow region: 0 = bow start (full beam), 1 = bow tip (centerline)
        const bowPos = (stationPos - bowStart) / (1.0 - bowStart);

        // Detect bow family from parameters
        const hasBulb = shipdVector[31] > 0.5; // bit_BB
        const beta = denormalized[8] ?? 0; // Flare angle (degrees)

        if (hasBulb) {
          // Bulbous bow: More gradual, rounded taper (not sharp V)
          // Use higher power for smoother curve
          longitudinalScale = Math.pow(1.0 - bowPos, 2.5);
        } else if (beta > 20) {
          // High flare bow (wave piercing): More gradual taper
          longitudinalScale = Math.pow(1.0 - bowPos, 2.2);
        } else {
          // Standard bow: Quadratic taper
          longitudinalScale = Math.pow(1.0 - bowPos, 2.0);
        }
      }
    } else if (region === "stern") {
      // Stern region: Taper from centerline at stern tip (pos=0.0) to full beam at midStart
      const ls = shipdVector[2] ?? 0.3; // Stern length ratio (already a ratio)

      // CRITICAL: Detect stern family from Atrans parameter
      // Use normalized vector values (0-1 range) for family detection and calculations
      const atransNorm = shipdVector[22] ?? 0; // Transom area coefficient (normalized 0-1)
      const bcTransNorm = shipdVector[28] ?? 0.1; // Transom width ratio (normalized 0-1)
      const rcTransNorm = shipdVector[29] ?? 0.25; // Stern curvature coefficient (normalized 0-1)

      if (stationPos <= ls) {
        // Position within stern region: 0 = stern tip (centerline), 1 = stern end (full beam)
        const sternPos = stationPos / ls;

        // TRANSOM STERN: When Atrans (normalized) > 0.5, maintain full beam until very close to transom
        // Then apply flat transom (not V-shape taper)
        // Note: Atrans normalized 0-1: 0 = pointed stern, 1 = full transom
        if (atransNorm > 0.5) {
          // Transom stern: Maintain full beam until last 5-10% of stern
          // Then transition to transom width (flat stern)
          const transomStartPos = 0.9; // Start transom at 90% of stern length

          if (sternPos < transomStartPos) {
            // Before transom: Maintain full beam (no V-shape taper)
            longitudinalScale = 1.0;
          } else {
            // At transom: Transition to transom width
            const transomBlend = (sternPos - transomStartPos) / (1.0 - transomStartPos);
            // Transom width is typically 70-100% of beam (bcTransNorm controls this)
            // bcTransNorm is normalized 0-1, map to 0.7-1.0 range
            const transomWidthRatio = 0.7 + bcTransNorm * 0.3; // 0.7 to 1.0
            longitudinalScale = 1.0 - (1.0 - transomWidthRatio) * transomBlend;
          }
        } else {
          // CRUISER/CANOE STERN: When Atrans < 0.5, use rounded/elliptical taper
          // Higher Rc_trans = fuller (rounder), Lower Rc_trans = finer (more pointed)
          // Use normalized vector value (0-1) for consistent exponent calculation
          const curveExponent = 2.0 + rcTransNorm * 1.0; // Range: 2.0 (standard) to 3.0 (very rounded)

          // Use smoother, more gradual taper for cruiser/canoe sterns
          // Elliptical taper: sternPos^exponent (instead of sternPos^2)
          longitudinalScale = Math.pow(sternPos, curveExponent);

          // Ensure minimum scale to avoid sharp V-shape
          if (longitudinalScale < 0.3 && sternPos > 0.3) {
            // For cruiser/canoe sterns, maintain reasonable width even near tip
            longitudinalScale = 0.3 + ((sternPos - 0.3) * 0.7) / 0.7;
          }
        }
      }
    }
    // Midship region: longitudinalScale = 1.0 (no taper, full beam)

    // === VALIDATE LONGITUDINAL SCALE ===
    // Ensure longitudinalScale is finite and positive
    if (!Number.isFinite(longitudinalScale) || longitudinalScale < 0) {
      console.warn("[ShipD generateStationOffsets] Invalid longitudinal scale", {
        longitudinalScale,
        region,
        stationPos,
      });
      longitudinalScale = 1.0; // Fallback to no taper
    }

    // Apply longitudinal scaling to half-breadth
    halfBreadth = halfBreadth * longitudinalScale;

    // === NaN DETECTION ===
    // Validate final half-breadth before storing to prevent NaN propagation
    if (!Number.isFinite(halfBreadth)) {
      console.warn("[ShipD generateStationOffsets] NaN detected in half-breadth calculation", {
        height,
        region,
        stationPos,
        longitudinalScale,
        preScaleHalfBreadth: halfBreadth / (longitudinalScale || 1),
      });
      halfBreadth = 0; // Fallback to centerline (zero width)
    }

    offsets[height] = Math.max(0, halfBreadth);
  }

  // CRITICAL: Ensure offsets are monotonic (non-decreasing with height) to prevent zig-zag patterns
  // Sort heights and enforce monotonicity
  const sortedHeights = Object.keys(offsets)
    .map(Number)
    .filter((h) => Number.isFinite(h))
    .sort((a, b) => a - b);

  let lastHalfBreadth = 0;
  for (const height of sortedHeights) {
    const currentHalfBreadth = offsets[height];
    // Ensure each offset is >= previous offset (monotonicity)
    // Allow small tolerance for numerical precision
    if (currentHalfBreadth < lastHalfBreadth - 0.001) {
      offsets[height] = lastHalfBreadth; // Use previous value to maintain monotonicity
    } else {
      lastHalfBreadth = currentHalfBreadth;
    }
  }

  // Ensure we have a point at the deck level (draftM) to close the top
  if (!(draftM in offsets)) {
    const maxHeight = Math.max(...Object.keys(offsets).map(Number));
    const maxHalfBreadth = offsets[maxHeight];
    offsets[draftM] = maxHalfBreadth * 0.95; // Slightly narrower at deck
  }

  // FINAL ENFORCEMENT: Baseline MUST be exactly 0 for proper keel closure
  // This ensures the keel is at the centerline regardless of any intermediate calculations
  // (longitudinal scaling, monotonicity enforcement, etc.)
  offsets[0] = 0;

  return offsets;
}

/**
 * Generates bulb offsets for a station in the bow region
 */
function generateBulbOffsets(
  stationPos: number,
  denormalized: Record<number, number>,
  shipdVector: number[],
  _lppM: number,
  beamM: number,
  draftM: number
): Record<number, number> {
  const offsets: Record<number, number> = {};

  // Bulb parameters - denormalized values are already the ratios to use
  const lbb = denormalized[33]; // Bulb length ratio (denormalized: actual ratio range 0-0.2)
  const hbb = denormalized[34]; // Bulb height ratio (denormalized: actual ratio range 0-1)
  const bbb = denormalized[35]; // Bulb width ratio (denormalized: actual ratio range 0-1)
  const lbbm = denormalized[36]; // Bulb asymmetry (fore/aft position) - denormalized: actual range -1 to +1
  const rbb = denormalized[37]; // Bulb fillet radius - denormalized: actual range 0.05-0.33

  // Bulb is only in forward section
  // CRITICAL: Use normalized vector for region boundaries (consistent with backend)
  const lb = shipdVector[1] ?? 0.3; // Bow length ratio (normalized 0-1)
  const bowStart = 1.0 - lb; // Start of bow region (0 = aft, 1 = forward)
  // Bulb extent: lbb is denormalized ratio (0-0.2), which is already the ratio of Lpp
  // Since stationPos is normalized (0-1), bulbExtent should also be normalized
  // lbb is already a ratio (e.g., 0.1 = 10% of Lpp), so normalized extent = lbb
  // Take 70% of bulb length for extent
  const bulbExtent = lbb * 0.7; // Bulb extends forward (70% of bulb length ratio, normalized)

  if (stationPos > bowStart && stationPos < bowStart + bulbExtent) {
    // Position within bulb (0 = start, 1 = forward end)
    const bulbPos = (stationPos - bowStart) / bulbExtent;

    // Apply asymmetry: lbbm shifts max bulb diameter fore/aft
    const asymmetryShift = (lbbm - 0.5) * 0.3; // -0.15 to +0.15
    const adjustedPos = Math.max(0, Math.min(1, bulbPos + asymmetryShift));

    const bulbHeight = hbb * draftM;
    const bulbWidth = bbb * beamM;

    // Longitudinal profile: use fillet radius to control shape
    // Higher rbb = rounder, lower rbb = more pointed
    const longitudinalExp = 1.5 + rbb * 1.0; // 1.5-2.5
    const longitudinalProfile = Math.pow(
      1 - Math.pow(adjustedPos, longitudinalExp),
      1 / longitudinalExp
    );

    const heightSteps = 12;
    for (let h = 0; h <= heightSteps; h++) {
      const height = (h / heightSteps) * bulbHeight;
      const heightRatio = height / bulbHeight;

      // Vertical profile: ellipsoid with fillet control
      const verticalExp = 1.8 + (1 - rbb) * 0.5; // 1.8-2.3
      const verticalProfile = Math.pow(1 - Math.pow(heightRatio, verticalExp), 1 / verticalExp);

      const halfBreadth = (bulbWidth / 2) * longitudinalProfile * verticalProfile;
      offsets[height] = Math.max(0, halfBreadth);
    }
  }

  return offsets;
}

/**
 * Generates skeg offsets for a station in the stern region
 * Skeg is a stern appendage that extends below the keel or at a vertical offset
 * Supports both single skeg and twin skeg configurations
 */
function generateSkegOffsets(
  stationPos: number,
  denormalized: Record<number, number>,
  shipdVector: number[],
  _lppM: number,
  beamM: number,
  draftM: number
): Record<number, number> {
  const offsets: Record<number, number> = {};

  // Skeg parameters
  const skZ = denormalized[23]; // SK_z - vertical offset control (0-1 normalized)
  const kappaSB = denormalized[38]; // Kappa_SB - skeg curvature parameter
  const lsb = denormalized[39]; // Lsb - skeg length ratio (0-1 normalized, range: 0-0.2)
  const hsb = denormalized[41]; // Hsb - skeg height ratio (for twin skeg, 0-1 normalized)
  const bsb = denormalized[42]; // Bsb - skeg breadth ratio (0-1 normalized)
  const lsbm = denormalized[43]; // Lsbm - skeg longitudinal moment coefficient (-1 to +1 normalized)
  const rsb = denormalized[44]; // Rsb - skeg radius coefficient (0.05-0.33 normalized)

  // Check if twin skeg (bit_SB > 0.5) or single skeg
  // For twin skeg, use Hsb; for single skeg, use HSBOA (index 40)
  const isTwinSkeg = shipdVector[32] > 0.5; // bit_SB
  const hsboa = denormalized[40]; // HSBOA - skeg height to breadth ratio (for single skeg)

  // Skeg is only in stern region
  // CRITICAL: stationPos is normalized (0-1), where 0=aft, 1=forward
  // ls (normalized) is the normalized position where stern ends (e.g., 0.3 means stern is 30% of normalized length)
  // lsb (denormalized) is the skeg length as a ratio (0-0.2 range, e.g., 0.1 = 10% ratio)
  // Since skeg is within stern region, and lsb is a ratio, we need to determine what lsb is a ratio of
  // Most likely: lsb is ratio of stern length, so skeg extent = lsb * ls (normalized stern length)
  const ls = shipdVector[2] ?? 0.3; // Stern length ratio (normalized 0-1, position where stern ends)
  const skegStart = 0.0; // Start at stern tip (position 0.0 = aft)
  // lsb is denormalized ratio (0-0.2), ls is normalized position (0-1)
  // If lsb is ratio of stern length: skeg extent = lsb * ls (both as ratios in normalized space)
  // This gives skeg extent as a fraction of the normalized coordinate system
  const skegExtent = lsb * ls; // Skeg extends aft from stern tip (normalized extent)

  if (stationPos >= skegStart && stationPos <= skegExtent) {
    // Position within skeg (0 = stern tip, 1 = skeg end)
    const skegPos = skegExtent > 0.001 ? stationPos / skegExtent : 0;

    // Apply longitudinal moment (Lsbm) for asymmetry
    // lsbm range: -1 to +1, where 0.5 is neutral
    // Convert to -0.3 to +0.3 shift
    const asymmetryShift = (lsbm - 0.5) * 0.6; // -0.3 to +0.3
    const adjustedPos = Math.max(0, Math.min(1, skegPos + asymmetryShift));

    // Skeg dimensions
    const skegHeight = isTwinSkeg ? hsb * draftM : hsboa * beamM; // Height for twin skeg, height-to-breadth ratio for single
    const skegBreadth = bsb * beamM;
    const skegVerticalOffset = skZ * draftM; // SK_z controls vertical position (0 = keel, 1 = draft)

    // Skeg extends below keel (negative heights) or at vertical offset
    // Vertical offset: positive = above keel, negative = below keel
    const skegBaseHeight = skegVerticalOffset - skegHeight; // Base of skeg (may be negative)

    // Longitudinal profile: use fillet radius to control shape
    // Higher rsb = rounder, lower rsb = more pointed
    // rsb range: 0.05-0.33, convert to exponent range 1.5-2.5
    const longitudinalExp = 1.5 + rsb * 1.0; // 1.5-2.5
    const longitudinalProfile = Math.pow(
      1 - Math.pow(adjustedPos, longitudinalExp),
      1 / longitudinalExp
    );

    // Generate skeg offsets at various heights
    const heightSteps = 12;
    for (let h = 0; h <= heightSteps; h++) {
      const heightRatio = h / heightSteps; // 0 to 1
      const height = skegBaseHeight + heightRatio * skegHeight; // Height from keel (may be negative)

      // Vertical profile: ellipsoid with fillet control
      // Higher rsb = rounder (lower exponent), lower rsb = more pointed (higher exponent)
      const verticalExp = 1.8 + (1 - rsb) * 0.5; // 1.8-2.3 (inverse relationship)
      const verticalProfile = Math.pow(1 - Math.pow(heightRatio, verticalExp), 1 / verticalExp);

      // Apply curvature parameter (Kappa_SB) for convex/concave control
      let curvatureEffect = 1.0;
      if (Math.abs(kappaSB - 0.5) > 0.1) {
        const convexEffect = (kappaSB - 0.5) * 2 * Math.sin((heightRatio * Math.PI) / 2) * 0.1;
        curvatureEffect = 1 + convexEffect;
      }

      const halfBreadth =
        (skegBreadth / 2) * longitudinalProfile * verticalProfile * curvatureEffect;
      offsets[height] = Math.max(0, halfBreadth);
    }
  }

  return offsets;
}
